export const getLocalDateYYYYMMDD = () => {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000; 
  const localDate = new Date(now.getTime() - offset);
  return localDate.toISOString().split('T')[0];
};

export async function validateDateAsync(dateStr, schoolConfig) {
  const todayStr = getLocalDateYYYYMMDD();
  const localDateObj = new Date(dateStr);
  const dayIndex = localDateObj.getDay(); // 0=Minggu, 6=Sabtu

  // 1. Masa Depan
  if (dateStr > todayStr) {
      return { isValid: false, message: "❌ Tanggal Masa Depan (Belum dapat diisi)." };
  }

  // 2. Hari Libur Rutin (Weekend)
  if (dayIndex === 0) {
      return { isValid: false, message: "⛔ Hari Minggu (Libur)." };
  }
  if (schoolConfig.hari_sekolah === 5 && dayIndex === 6) {
      return { isValid: false, message: "⛔ Hari Sabtu (Sekolah 5 Hari Kerja)." };
  }

  // 3. Cek Kalender Pendidikan di Database
  try {
      const { data: libur } = await supabase
          .from('kalender_pendidikan')
          .select('jenis, keterangan')
          .eq('tanggal', dateStr)
          .maybeSingle();

      if (libur) {
          const label = libur.jenis.replace(/_/g, ' ');
          return { isValid: false, message: `🏖️ ${label}: ${libur.keterangan || ''}` };
      }
  } catch (err) {
      console.error("Error check holiday", err);
  }

  return { isValid: true, message: "" };
}

