export function attachLoginEvents(onSuccess) {
    const form = document.getElementById('loginForm');
    if(!form) return;

    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const btn = document.getElementById('btnLogin');
        const originalText = btn.innerHTML;
        btn.innerHTML = `<div class="loader border-white border-t-transparent w-5 h-5 mx-auto"></div>`;
        btn.disabled = true;

        const username = document.getElementById("username").value.trim();
        const password = document.getElementById("password").value.trim();

        try {
            const { data, error } = await supabase.from("guru").select("*").eq("username", username).eq("password", password).maybeSingle();
            if (error) throw error;
            if (!data) throw new Error("User tidak ditemukan atau password salah");

            onSuccess(data);
        } catch (err) {
            console.error(err);
            showToast("Login gagal: " + err.message, "error");
            btn.innerHTML = originalText;
            btn.disabled = false;
        }
    });
}

import { supabase } from '../config.js';
import { showToast, validateDateAsync, getLocalDateYYYYMMDD } from '../utils.js';

let localTanggal = getLocalDateYYYYMMDD();
let localSiswa = [];
let localSchoolConfig = { hari_sekolah: 5 };
let currentGuruId = null;

export async function initKehadiran(guruId, schoolConfig) {
    currentGuruId = guruId;
    localSchoolConfig = schoolConfig;
    localTanggal = getLocalDateYYYYMMDD();

    // Render Shell
    const content = document.getElementById('mainContent');
    content.innerHTML = `
        <div class="max-w-4xl mx-auto space-y-6 fade-in">
