async function fetchSiswaBinaan() {
    const { data, error } = await supabase.from("bimbingan").select("siswa(*)").eq("id_guru", currentGuruId);
    if (error) { console.error("Error fetch siswa:", error); return []; }
    return data.map(item => item.siswa).filter(Boolean);
}

async function loadSiswaList() {
    // Validasi
    const validation = await validateDateAsync(localTanggal, localSchoolConfig);
    const isLocked = !validation.isValid;

    const alertBox = document.getElementById('dateAlertBox');
    const btnSimpan = document.getElementById('btnSimpan');
    const btnHapus = document.getElementById('btnHapus');
    const btnText = document.getElementById('btnSimpanText');

    // Update UI berdasarkan Validasi
    if (alertBox) {
        if (isLocked) {
            alertBox.className = "mb-4 p-3 rounded-lg text-sm font-medium border bg-amber-900/30 border-amber-600/50 text-amber-200 block alert-enter";
            alertBox.innerText = validation.message;
        } else {
            alertBox.className = "hidden";
            alertBox.innerText = "";
        }
    }

    if (btnSimpan) btnSimpan.disabled = isLocked;
    if (btnHapus) btnHapus.disabled = isLocked;

    const container = document.getElementById('siswaListContainer');
    container.innerHTML = `<div class="p-8 text-center text-slate-500"><div class="loader mx-auto mb-2"></div>Memuat data siswa...</div>`;

    localSiswa = await fetchSiswaBinaan();

    if (localSiswa.length === 0) {
        container.innerHTML = `<div class="p-8 text-center text-slate-500"><i class="ph ph-empty text-4xl mb-2"></i><p>Tidak ada siswa binaan ditemukan.</p></div>`;
        return;
    }

    // Ambil data existing dari Supabase
    let kehadiranMap = {};
    let isEditMode = false;
    const siswaIds = localSiswa.map(s => s.id);
    const { data: kehadiranList } = await supabase.from('kehadiran').select('id_siswa, status').eq('tanggal', localTanggal).in('id_siswa', siswaIds);

    if (kehadiranList && kehadiranList.length > 0) {
        isEditMode = true;
        kehadiranList.forEach(k => { kehadiranMap[k.id_siswa] = k.status; });
    }

    // Update Tombol Simpan
    if (btnText && btnSimpan && btnHapus) {
        if (isLocked) {
             btnText.innerText = "Input Dikunci";
             btnSimpan.classList.add('bg-slate-600'); 
             btnSimpan.classList.remove('bg-emerald-600', 'bg-blue-600');
             btnHapus.classList.add('hidden');
        } else {
            btnText.innerText = isEditMode ? "Update Kehadiran" : "Simpan Kehadiran";
            if(isEditMode) {
              btnSimpan.className = "bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-xl font-bold shadow-lg transition flex items-center gap-2";
              btnHapus.classList.remove('hidden');
            } else {
              btnSimpan.className = "bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-3 rounded-xl font-bold shadow-lg transition flex items-center gap-2";
              btnHapus.classList.add('hidden');
            }
        }
    }

    // Render List
    let html = '<div class="divide-y divide-slate-700">';
    const statusOptions = [{ val: 'HADIR', label: '🟢 Hadir' }, { val: 'IZIN', label: '🟡 Izin' }, { val: 'ALPA', label: '🔴 Alpa' }, { val: 'SAKIT', label: '🔵 Sakit' }];

    for (const s of localSiswa) {
        const savedStatus = kehadiranMap[s.id]; 
        const currentStatus = savedStatus || 'HADIR'; 
        const selectClass = savedStatus ? "border-blue-500 bg-blue-900/20 ring-1 ring-blue-500/50 text-blue-100 font-medium" : "bg-slate-900 border-slate-600 text-slate-300";
        const disabledAttr = isLocked ? 'disabled' : '';
        const cursorClass = isLocked ? 'disabled-input' : 'cursor-pointer';

        const optionsHtml = statusOptions.map(opt => {
            const isSelected = currentStatus === opt.val;
            const labelText = (savedStatus === opt.val) ? `${opt.label} ✓` : opt.label;
            return `<option value="${opt.val}" ${isSelected ? 'selected' : ''}>${labelText}</option>`;
        }).join('');

        html += `
          <div class="p-4 hover:bg-slate-750 transition flex flex-col sm:flex-row sm:items-center justify-between gap-4 group">
            <div class="flex items-center gap-4">
              <div class="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center text-slate-300 font-bold">
                ${s.nama.charAt(0)}
              </div>
              <div>
                <p class="font-medium text-white">${s.nama}</p>
                <p class="text-sm text-slate-400 font-mono">${s.nisn || '-'}</p>
              </div>
            </div>
            <div class="w-full sm:w-48 relative">
              <select id="status-${s.id}" ${disabledAttr} class="w-full border rounded px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all ${selectClass} ${cursorClass}">${optionsHtml}</select>
            </div>
          </div>
        `;
    }
    html += '</div>';
    container.innerHTML = html;
}

async function simpanKehadiran() {
    const btn = document.getElementById('btnSimpan');
    const originalText = btn.innerHTML;
    btn.innerText = "Memproses...";
    btn.disabled = true;

    try {
        const siswaIds = localSiswa.map(s => s.id);
        // Cek existing untuk Upsert manual (supaya aman)
        const { data: existingData } = await supabase.from('kehadiran').select('id, id_siswa').eq('tanggal', localTanggal).in('id_siswa', siswaIds);
        const existingMap = {};
        existingData?.forEach(e => existingMap[e.id_siswa] = e.id);

        const updates = [];
        const inserts = [];

        localSiswa.forEach(s => {
            const status = document.getElementById(`status-${s.id}`).value;
            if (existingMap[s.id]) {
                updates.push(supabase.from('kehadiran').update({ status }).eq('id', existingMap[s.id]));
            } else {
                inserts.push({ id_siswa: s.id, id_guru: currentGuruId, tanggal: localTanggal, status: status });
            }
        });

        if (updates.length > 0) await Promise.all(updates);
        if (inserts.length > 0) await supabase.from('kehadiran').insert(inserts);

        showToast("Kehadiran disimpan", "success");
        loadSiswaList();
    } catch (err) {
        showToast("Gagal menyimpan: " + err.message, "error");
    } finally {
        btn.innerHTML = originalText;
        btn.disabled = false;
    }
}

async function hapusKehadiran() {
    if (!confirm("Hapus data kehadiran tanggal ini?")) return;
    try {
        await supabase.from('kehadiran').delete().eq('id_guru', currentGuruId).eq('tanggal', localTanggal);
        showToast("Data dihapus");
        loadSiswaList();
    } catch(e) { showToast("Gagal hapus", "error"); }
}

import { supabase } from './config.js';
import { renderLayout } from './layout.js';
import { renderLogin, attachLoginEvents } from './pages/login.js';
import { initKehadiran } from './pages/kehadiran.js';
import { showToast, renderLoader } from './utils.js';

// --- STATE ---
let currentGuru = null;
let activeView = 'KEHADIRAN';
let schoolConfig = { hari_sekolah: 5 };

const app = document.getElementById('app');
const SESSION_KEY = 'gurwal_session_v2';

// --- INIT ---
async function initApp() {
    checkSession();
}

function checkSession() {
    try {
        const stored = localStorage.getItem(SESSION_KEY);
        if (stored) {
            const session = JSON.parse(stored);
            if (session && session.guru) {
                currentGuru = session.guru;
                loadDashboard();
                return;
            }
        }
    } catch (e) { localStorage.removeItem(SESSION_KEY); }
    showLogin();
}

function showLogin() {
    app.innerHTML = renderLogin();
    attachLoginEvents((guruData) => {
        currentGuru = guruData;
        localStorage.setItem(SESSION_KEY, JSON.stringify({ guru: guruData }));
        showToast(`Selamat datang, ${guruData.nama}!`);
        loadDashboard();
    });
}

async function loadDashboard() {
    // Load config first
    try {
        const { data } = await supabase.from('sekolah').select('hari_sekolah').limit(1).maybeSingle();
        if (data) schoolConfig.hari_sekolah = data.hari_sekolah;
    } catch(e) { console.log('Config load error', e); }

    // Render Layout
    app.innerHTML = renderLayout(currentGuru.nama, currentGuru.username);

    // Attach Global Nav Logic
    window.navigateTo = (view) => {
        activeView = view;
        updateSidebarUI();

        // Auto-close sidebar on mobile
        const sidebar = document.querySelector('aside');
        if (sidebar && sidebar.classList.contains('absolute')) {
            toggleSidebar();
        }

        const contentEl = document.getElementById('mainContent');
        if(contentEl) {
            contentEl.innerHTML = renderLoader();
            setTimeout(() => routePage(view, contentEl), 50);
        }
    };

    window.logout = () => {
        localStorage.removeItem(SESSION_KEY);
        window.location.reload();
    };

    window.toggleSidebar = () => {
        const sidebar = document.querySelector('aside');
        if(sidebar) {
            sidebar.classList.toggle('hidden');
            sidebar.classList.toggle('absolute');
            sidebar.classList.toggle('h-full');
        }
    };

    // Default Route
    window.navigateTo('KEHADIRAN');
}

function updateSidebarUI() {
    document.querySelectorAll('.nav-item').forEach(el => {
        if (el.dataset.view === activeView) {
            el.classList.add('bg-indigo-600', 'text-white');
            el.classList.remove('text-slate-400', 'hover:bg-slate-800');
        } else {
            el.classList.remove('bg-indigo-600', 'text-white');
            el.classList.add('text-slate-400', 'hover:bg-slate-800');
        }
    });
    const mobileTitle = document.getElementById('mobileTitle');
    if(mobileTitle) mobileTitle.innerText = activeView.replace('_', ' ');
}

function routePage(view, container) {
    switch (view) {
        case 'KEHADIRAN':
            initKehadiran(currentGuru.id, schoolConfig);
            break;
        case 'PRESTASI':
            container.innerHTML = `<div class="p-10 text-center text-gray-500">Halaman Prestasi (Placeholder Modular)</div>`;
            break;
        case 'PELANGGARAN':
            container.innerHTML = `<div class="p-10 text-center text-gray-500">Halaman Pelanggaran (Placeholder Modular)</div>`;
            break;
        case 'JADWAL':
            container.innerHTML = `<div class="p-10 text-center text-gray-500">Halaman Jadwal (Placeholder Modular)</div>`;
            break;
        case 'NILAI':
            container.innerHTML = `<div class="p-10 text-center text-gray-500">Halaman Nilai (Placeholder Modular)</div>`;
            break;
        case 'LAPORAN':
            container.innerHTML = `<div class="p-10 text-center text-gray-500">Halaman Laporan (Placeholder Modular)</div>`;
            break;
        default:
            container.innerHTML = `<div class="p-10 text-center text-gray-500">Halaman tidak ditemukan</div>`;
    }
}

// Start
initApp();

const CACHE_NAME = 'gurwal-spa-v1';

// Daftar file statis yang harus di-cache agar aplikasi bisa dibuka offline
// Perhatikan: Path relatif terhadap lokasi sw.js (folder spa/)
const ASSETS_TO_CACHE = [
  './index.html',
  './manifest.json',
  './js/config.js',
  './js/utils.js',
  './js/layout.js',
  './js/app.js',
  './js/pages/login.js',
  './js/pages/kehadiran.js',
  // External Libraries (CDN) - Penting untuk di-cache
  'https://cdn.tailwindcss.com',
  'https://unpkg.com/@phosphor-icons/web',
  'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700&display=swap',
  'https://cdn.sheetjs.com/xlsx-0.20.1/package/dist/xlsx.full.min.js',
  'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js',
  'https://cdnjs.cloudflare.com/ajax/libs/jspdf-autotable/3.8.1/jspdf.plugin.autotable.min.js',
  'https://esm.sh/@supabase/supabase-js@2'
];

// 1. INSTALL: Cache semua aset statis
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      console.log('[SW] Caching App Shell');
      return cache.addAll(ASSETS_TO_CACHE);
    })
  );
  self.skipWaiting();
});

// 2. ACTIVATE: Hapus cache lama jika ada update versi
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cache) => {
          if (cache !== CACHE_NAME) {
            console.log('[SW] Clearing old cache', cache);
            return caches.delete(cache);
          }
        })
      );
    })
  );
  self.clients.claim();
});

// 3. FETCH: Strategi Caching
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);

  // A. Permintaan ke Supabase (API) -> Network First, Fallback Error
  // Kita tidak ingin cache data API secara agresif karena data siswa bisa berubah
  if (url.hostname.includes('supabase.co')) {
    return; // Biarkan browser menangani secara normal (online only)
  }

  // B. Aset Statis (JS, HTML, CSS, Images) -> Cache First, Fallback Network
  event.respondWith(
    caches.match(event.request).then((cachedResponse) => {
      if (cachedResponse) {
        return cachedResponse;
      }
      return fetch(event.request).then((networkResponse) => {
        // Cache file baru yang diambil (opsional, hati-hati cache bloating)
        // Disini kita hanya fetch tanpa cache dinamis untuk menjaga konsistensi
        return networkResponse;
      });
    })
  );
});

