    data.forEach(item => {
        html += `<tr class="hover:bg-slate-750 transition">
            <td class="p-4 text-slate-400 whitespace-nowrap">${item.tanggal}</td>
            <td class="p-4 font-bold text-white">${item.siswa?.nama}</td>
            <td class="p-4">${item.deskripsi}</td>
