            const id = e.currentTarget.dataset.id;
            if(confirm('Hapus data ini?')) {
                const { error } = await supabase.from('prestasi').delete().eq('id', id);
                if(!error) {
                    showToast('Data dihapus', 'success');
                    loadPrestasiList();
                } else {
                    showToast('Gagal menghapus', 'error');
