async function savePrestasi() {
    const id_siswa = document.getElementById('presSiswa').value;
    const tanggal = document.getElementById('presTanggal').value;
    const deskripsi = document.getElementById('presJudul').value;
    const tingkat = document.getElementById('presTingkat').value;

    if(!id_siswa || !deskripsi || !tanggal) {
        showToast("Mohon lengkapi data wajib", "error");
        return;
    }

    const btn = document.getElementById('btnSave');
    btn.innerText = 'Menyimpan...';
    btn.disabled = true;

    try {
        const { error } = await supabase.from('prestasi').insert([{
            id_guru: currentGuruId, id_siswa, tanggal, deskripsi, tingkat
        }]);

        if (error) throw error;

        showToast("Prestasi berhasil disimpan", "success");
