async function loadFormNilai() {
    const id_kelas = document.getElementById('filterKelas').value;
    const id_mapel = document.getElementById('filterMapel').value;
    const jenis = document.getElementById('filterJenis').value;

    if(!id_kelas || !id_mapel) {
        showToast("Mohon pilih Kelas dan Mata Pelajaran", "error");
        return;
    }

    const container = document.getElementById('nilaiContainer');
    const list = document.getElementById('listSiswaNilai');

    container.classList.remove('hidden');
    list.innerHTML = `<div class="p-12 text-center text-slate-500">${renderLoader()}</div>`;

    // 1. Get Students
    const { data: students } = await supabase.from('siswa').select('id, nama, nisn').eq('id_kelas', id_kelas).order('nama');

    if (!students || students.length === 0) {
        list.innerHTML = `<div class="p-8 text-center text-slate-500">Tidak ada siswa di kelas ini.</div>`;
        return;
    }

    // 2. Get Existing Grades
    const { data: grades } = await supabase.from('nilai')
        .select('id_siswa, nilai')
        .eq('id_guru', currentGuruId)
        .eq('id_mapel', id_mapel)
        .eq('jenis', jenis)
        .in('id_siswa', students.map(s => s.id));

    const gradeMap = {};
    if(grades) grades.forEach(g => gradeMap[g.id_siswa] = g.nilai);

    // 3. Render Table
    let html = `<table class="w-full text-left text-sm text-slate-300">
        <thead class="bg-slate-700 text-slate-100 font-bold uppercase text-xs">
            <tr>
                <th class="p-4 w-10 text-center">No</th>
                <th class="p-4">Nama Siswa</th>
                <th class="p-4 w-40 text-center">Nilai (0-100)</th>
            </tr>
        </thead>
        <tbody class="divide-y divide-slate-700">`;

    students.forEach((s, idx) => {
        const val = gradeMap[s.id] !== undefined ? gradeMap[s.id] : '';
        html += `<tr class="hover:bg-slate-750 transition">
            <td class="p-4 text-center text-slate-500">${idx + 1}</td>
            <td class="p-4">
                <div class="font-bold text-white">${s.nama}</div>
                <div class="text-xs text-slate-500 font-mono">${s.nisn}</div>
            </td>
            <td class="p-4 text-center">
                <input type="number" min="0" max="100" 
                    data-id="${s.id}" 
                    value="${val}" 
                    class="input-nilai w-24 bg-slate-900 border border-slate-600 rounded-lg p-2 text-center text-white font-mono focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 outline-none transition"
                    placeholder="-"
                >
            </td>
        </tr>`;
    });
    html += `</tbody></table>`;
    list.innerHTML = html;
}

async function saveNilaiBatch() {
    const id_mapel = document.getElementById('filterMapel').value;
    const jenis = document.getElementById('filterJenis').value;
    const inputs = document.querySelectorAll('.input-nilai');
    const today = getLocalDateYYYYMMDD();

    const btn = document.getElementById('btnSaveNilai');
    btn.innerHTML = `<div class="loader w-4 h-4 border-t-transparent border-white inline-block mr-2"></div> Proses...`;
    btn.disabled = true;

    try {
        const updates = [];
        const idsToDelete = [];

        inputs.forEach(inp => {
            const val = inp.value;
            const id_siswa = inp.dataset.id;

            if (val !== '') {
                // Prepare Insert/Update payload
                updates.push({
                    id_guru: currentGuruId,
                    id_siswa: id_siswa,
                    id_mapel: id_mapel,
                    jenis: jenis,
                    nilai: parseFloat(val),
                    tanggal: today
                });
            } else {
                // If empty, mark for deletion (if needed logic, or simply ignore)
                // Disini kita biarkan user menghapus nilai dengan mengosongkan input
                // Namun karena Upsert tidak support delete otomatis, kita harus delete manual yg kosong.
                idsToDelete.push(id_siswa);
            }
        });

        // 1. Delete values that were cleared
        if (idsToDelete.length > 0) {
            await supabase.from('nilai').delete()
                .eq('id_guru', currentGuruId)
                .eq('id_mapel', id_mapel)
                .eq('jenis', jenis)
                .in('id_siswa', idsToDelete);
        }

        // 2. Upsert new values (Insert or Update)
        // Kita perlu delete dulu yang mau diupdate untuk menghindari duplikat jika tidak ada unique constraint yang pas,
        // TAPI sebaiknya pakai UPSERT. Supabase butuh conflict constraint. 
        // Asumsi tabel 'nilai' belum tentu ada unique key (id_guru, id_siswa, id_mapel, jenis).
        // Jadi cara aman: Delete for these students first, then Insert.

        const idsToUpdate = updates.map(u => u.id_siswa);
        if (idsToUpdate.length > 0) {
            // Hapus data lama untuk siswa yang akan diupdate (Batch Delete)
            await supabase.from('nilai').delete()
                .eq('id_guru', currentGuruId)
                .eq('id_mapel', id_mapel)
                .eq('jenis', jenis)
                .in('id_siswa', idsToUpdate);

            // Insert data baru (Batch Insert)
            const { error } = await supabase.from('nilai').insert(updates);
            if (error) throw error;
        }

        showToast("Nilai berhasil disimpan!", "success");

    } catch (e) {
        console.error(e);
        showToast("Gagal menyimpan: " + e.message, "error");
    } finally {
        btn.innerHTML = `<i class="ph ph-floppy-disk"></i> Simpan Perubahan`;
        btn.disabled = false;
    }
}

