    document.getElementById('btnExportXls').onclick = exportToExcel;
    document.getElementById('btnExportPdf').onclick = exportToPDF;
}

async function getExportData() {
    const start = document.getElementById('exportStartDate').value;
    const end = document.getElementById('exportEndDate').value;

    if (start > end) {
        showToast("Tanggal mulai tidak boleh lebih besar dari tanggal akhir", "error");
        return null;
    }

    showToast("Sedang mengambil data...", "info");

    const { data, error } = await supabase
        .from('kehadiran')
        .select(`tanggal, status, siswa (nama, nisn, kelas (nama))`)
        .eq('id_guru', currentGuruId)
        .gte('tanggal', start)
        .lte('tanggal', end)
        .order('tanggal', { ascending: true })
        .order('siswa(nama)', { ascending: true });

    if (error) {
        showToast("Gagal mengambil data", "error");
        return null;
    }

    if (!data || data.length === 0) {
        showToast("Tidak ada data pada periode ini", "warning");
        return null;
    }

    return {
        start, end,
        rows: data.map(row => ({
            tanggal: row.tanggal,
            nama: row.siswa?.nama || 'Unknown',
            nisn: row.siswa?.nisn || '-',
            // @ts-ignore
            kelas: row.siswa?.kelas?.nama || '-',
            status: row.status
        }))
    };
}

async function exportToExcel() {
    const result = await getExportData();
    if (!result) return;

    try {
        const ws = XLSX.utils.json_to_sheet(result.rows);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Laporan");
        XLSX.writeFile(wb, `Laporan_Kehadiran_${result.start}_sd_${result.end}.xlsx`);
        showToast("Excel berhasil diunduh");
    } catch (e) {
        console.error(e);
        showToast("Gagal export Excel", "error");
    }
}

async function exportToPDF() {
    const result = await getExportData();
    if (!result) return;

    try {
        const doc = new window.jspdf.jsPDF();

        // Header
        doc.setFontSize(16);
        doc.setFont("helvetica", "bold");
        doc.text(`LAPORAN KEHADIRAN SISWA BINAAN`, 105, 20, { align: "center" });

        doc.setFontSize(11);
        doc.setFont("helvetica", "normal");
        doc.text(`Guru Wali: ${currentGuruName}`, 14, 30);
        doc.text(`Periode: ${result.start} s/d ${result.end}`, 14, 36);

        const tableRows = result.rows.map(row => [row.tanggal, row.nama, row.kelas, row.status]);

        doc.autoTable({
            startY: 45,
            head: [['Tanggal', 'Nama Siswa', 'Kelas', 'Status']],
            body: tableRows,
            theme: 'grid',
            headStyles: { fillColor: [63, 81, 181] },
            styles: { fontSize: 10 }
        });

        doc.save(`Laporan_${result.start}_sd_${result.end}.pdf`);
        showToast("PDF berhasil diunduh");
    } catch (e) {
        console.error(e);
        showToast("Gagal export PDF", "error");
    }
}

import { supabase } from './config.js';
import { renderLayout } from './layout.js';
import { renderLogin, attachLoginEvents } from './pages/login.js';
