                    <div class="p-8 text-center text-slate-500"><div class="loader mx-auto mb-2"></div>Memuat...</div>
                </div>

                <div class="flex gap-3 justify-end">
                    <button id="btnHapus" class="hidden bg-red-600 hover:bg-red-700 text-white px-5 py-2.5 rounded-xl font-bold shadow-lg transition flex items-center gap-2 text-sm border border-red-500/50">
