async function fetchSiswaBinaan() {
    const { data, error } = await supabase.from("bimbingan").select("siswa(*)").eq("id_guru", currentGuruId);
    if (error) { console.error("Error fetch siswa:", error); return []; }
    return data.map(item => item.siswa).filter(Boolean);
}

async function loadSiswaList() {
    const container = document.getElementById('siswaListContainer');
    const alertBox = document.getElementById('dateAlertBox');
    const btnSimpan = document.getElementById('btnSimpan');
    const btnHapus = document.getElementById('btnHapus');
    const btnText = document.getElementById('btnSimpanText');

    // 1. Validasi Tanggal
    const validation = await validateDateAsync(localTanggal, localSchoolConfig);
    const todayStr = getLocalDateYYYYMMDD();

    // LOGIC: Kunci input HANYA jika tanggal masa depan.
    // Hari libur / minggu tetap bisa diinput (unlocked) tapi tampilkan warning.
    const isFuture = localTanggal > todayStr;
    const isLocked = isFuture;
    const isWarning = !validation.isValid && !isFuture;

    // Update UI Alert
    if (alertBox) {
        if (isLocked) {
            // Error Masa Depan
            alertBox.className = "mb-4 p-3 rounded-lg text-sm font-medium border bg-red-900/30 border-red-600/50 text-red-200 block alert-enter flex items-center gap-2";
            alertBox.innerHTML = `<i class="ph ph-prohibit"></i> ${validation.message || 'Tanggal Masa Depan'}`;
        } else if (isWarning) {
            // Warning Libur (Tetap Bisa Input)
            alertBox.className = "mb-4 p-3 rounded-lg text-sm font-medium border bg-amber-900/30 border-amber-600/50 text-amber-200 block alert-enter flex items-center gap-2";
            alertBox.innerHTML = `<i class="ph ph-warning"></i> ${validation.message} <span class="ml-auto text-xs bg-amber-900/50 px-2 py-1 rounded border border-amber-700">Input Diizinkan</span>`;
        } else {
            alertBox.className = "hidden";
            alertBox.innerText = "";
        }
    }

    if (btnSimpan) btnSimpan.disabled = isLocked;
    if (btnHapus) btnHapus.disabled = isLocked;

    // Save current scroll position
    const scrollTop = container.scrollTop;

    // Render Loader only if initial load or class change
    if (container.innerHTML.includes("loader")) {
        container.innerHTML = `<div class="p-8 text-center text-slate-500"><div class="loader mx-auto mb-2"></div>Memuat data siswa...</div>`;
    }

    localSiswa = await fetchSiswaBinaan();

    if (localSiswa.length === 0) {
        container.innerHTML = `<div class="p-8 text-center text-slate-500"><i class="ph ph-empty text-4xl mb-2"></i><p>Tidak ada siswa binaan ditemukan.</p></div>`;
        return;
    }

    // Ambil data existing dari Supabase
    let kehadiranMap = {};
    let isEditMode = false;
    const siswaIds = localSiswa.map(s => s.id);
    const { data: kehadiranList } = await supabase.from('kehadiran').select('id_siswa, status').eq('tanggal', localTanggal).in('id_siswa', siswaIds);

    if (kehadiranList && kehadiranList.length > 0) {
        isEditMode = true;
        kehadiranList.forEach(k => { kehadiranMap[k.id_siswa] = k.status; });
    }

    // Update Tombol Simpan
    if (btnText && btnSimpan && btnHapus) {
        if (isLocked) {
             btnText.innerText = "Input Dikunci";
             btnSimpan.classList.add('bg-slate-600', 'cursor-not-allowed', 'opacity-50'); 
             btnSimpan.classList.remove('bg-emerald-600', 'bg-blue-600', 'hover:bg-emerald-700', 'hover:bg-blue-700');
             btnHapus.classList.add('hidden');
        } else {
            btnSimpan.classList.remove('bg-slate-600', 'cursor-not-allowed', 'opacity-50');
            btnText.innerText = isEditMode ? "Update Kehadiran" : "Simpan Kehadiran";
            if(isEditMode) {
              btnSimpan.className = "bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-xl font-bold shadow-lg transition flex items-center gap-2 text-sm border border-blue-500/50";
              btnHapus.classList.remove('hidden');
            } else {
              btnSimpan.className = "bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-2.5 rounded-xl font-bold shadow-lg transition flex items-center gap-2 text-sm border border-emerald-500/50";
              btnHapus.classList.add('hidden');
            }
        }
    }

    // Render List
    let html = '<div class="divide-y divide-slate-700">';
    const statusOptions = [{ val: 'HADIR', label: '🟢 Hadir' }, { val: 'IZIN', label: '🟡 Izin' }, { val: 'ALPA', label: '🔴 Alpa' }, { val: 'SAKIT', label: '🔵 Sakit' }];

    for (const s of localSiswa) {
        const savedStatus = kehadiranMap[s.id]; 
        const currentStatus = savedStatus || 'HADIR'; 
        const selectClass = savedStatus ? "border-blue-500 bg-blue-900/20 ring-1 ring-blue-500/50 text-blue-100 font-medium" : "bg-slate-900 border-slate-600 text-slate-300";
        const disabledAttr = isLocked ? 'disabled' : '';
        const cursorClass = isLocked ? 'disabled-input' : 'cursor-pointer';

        const optionsHtml = statusOptions.map(opt => {
            const isSelected = currentStatus === opt.val;
            const labelText = (savedStatus === opt.val) ? `${opt.label} ✓` : opt.label;
            return `<option value="${opt.val}" ${isSelected ? 'selected' : ''}>${labelText}</option>`;
        }).join('');

        html += `
          <div class="p-4 hover:bg-slate-750 transition flex flex-col sm:flex-row sm:items-center justify-between gap-4 group">
            <div class="flex items-center gap-4">
              <div class="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center text-slate-300 font-bold border border-slate-600 text-sm">
                ${s.nama.charAt(0)}
              </div>
              <div>
                <p class="font-medium text-white">${s.nama}</p>
                <p class="text-xs text-slate-400 font-mono">${s.nisn || '-'}</p>
              </div>
            </div>
            <div class="w-full sm:w-48 relative">
              <select id="status-${s.id}" ${disabledAttr} class="w-full border rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all ${selectClass} ${cursorClass}">${optionsHtml}</select>
            </div>
          </div>
        `;
    }
    html += '</div>';
    container.innerHTML = html;
    // Restore scroll
    container.scrollTop = scrollTop;
}

async function simpanKehadiran() {
    const btn = document.getElementById('btnSimpan');
    const originalText = btn.innerHTML;
    btn.innerHTML = `<div class="loader w-4 h-4 border-white border-t-transparent mx-auto"></div>`;
    btn.disabled = true;

    try {
        const siswaIds = localSiswa.map(s => s.id);
        const { data: existingData } = await supabase.from('kehadiran').select('id, id_siswa').eq('tanggal', localTanggal).in('id_siswa', siswaIds);
        const existingMap = {};
        existingData?.forEach(e => existingMap[e.id_siswa] = e.id);

        const updates = [];
        const inserts = [];

        localSiswa.forEach(s => {
            const status = document.getElementById(`status-${s.id}`).value;
            if (existingMap[s.id]) {
                updates.push(supabase.from('kehadiran').update({ status }).eq('id', existingMap[s.id]));
            } else {
                inserts.push({ id_siswa: s.id, id_guru: currentGuruId, tanggal: localTanggal, status: status });
            }
        });

        if (updates.length > 0) await Promise.all(updates);
        if (inserts.length > 0) await supabase.from('kehadiran').insert(inserts);

        showToast("Kehadiran berhasil disimpan!", "success");
        loadSiswaList();
    } catch (err) {
        showToast("Gagal menyimpan: " + err.message, "error");
    } finally {
        btn.innerHTML = originalText;
        btn.disabled = false;
    }
}

async function hapusKehadiran() {
    if (!confirm("Hapus data kehadiran tanggal ini?")) return;
    try {
        await supabase.from('kehadiran').delete().eq('id_guru', currentGuruId).eq('tanggal', localTanggal);
        showToast("Data kehadiran dihapus", "warning");
        loadSiswaList();
    } catch(e) { showToast("Gagal hapus", "error"); }
}

// --- LOGIKA LAPORAN ---

async function getExportData() {
    const start = document.getElementById('exportStartDate').value;
    const end = document.getElementById('exportEndDate').value;

    if (start > end) {
        showToast("Tanggal mulai tidak boleh lebih besar dari tanggal akhir", "error");
        return null;
    }

    const { data, error } = await supabase
        .from('kehadiran')
        .select(`tanggal, status, siswa (nama, nisn, kelas (nama))`)
        .eq('id_guru', currentGuruId)
        .gte('tanggal', start)
        .lte('tanggal', end)
        .order('tanggal', { ascending: true })
        .order('siswa(nama)', { ascending: true });

    if (error) {
        showToast("Gagal mengambil data laporan", "error");
        return null;
    }

    if (!data || data.length === 0) {
        showToast("Tidak ada data pada periode ini", "warning");
        return null;
    }

    return {
        start, end,
        rows: data.map(row => ({
            tanggal: row.tanggal,
            nama: row.siswa?.nama || 'Unknown',
            nisn: row.siswa?.nisn || '-',
            // @ts-ignore
            kelas: row.siswa?.kelas?.nama || '-',
            status: row.status
        }))
    };
}

async function exportToExcel() {
    const btn = document.getElementById('btnExportXls');
    const originalText = btn.innerHTML;
    btn.innerHTML = `<div class="loader w-4 h-4 border-white border-t-transparent inline-block"></div>`;
    btn.disabled = true;

    const result = await getExportData();
    if (!result) {
        btn.innerHTML = originalText;
        btn.disabled = false;
        return;
    }

    try {
        // --- 1. Pivot Logic (Tanggal sebagai Kolom) ---
        const rawData = result.rows;
        const uniqueDates = [...new Set(rawData.map(item => item.tanggal))].sort();
        const studentMap = {};

        // Group by Student
        rawData.forEach(item => {
            const key = item.nisn && item.nisn !== '-' ? item.nisn : item.nama;
            if (!studentMap[key]) {
                studentMap[key] = { 
                    nama: item.nama, 
                    kelas: item.kelas, 
                    nisn: item.nisn, 
                    attendance: {} 
                };
            }
            studentMap[key].attendance[item.tanggal] = item.status;
        });

        // --- 2. Prepare Sheet Rows ---
        // Header
        const headers = ["Nama Siswa", "NISN", "Kelas", ...uniqueDates];
        const sheetData = [headers];

        // Rows
        Object.values(studentMap)
            .sort((a, b) => a.nama.localeCompare(b.nama))
            .forEach(student => {
                const row = [
                    student.nama, 
                    student.nisn, 
                    student.kelas,
                    ...uniqueDates.map(date => student.attendance[date] || '-')
                ];
                sheetData.push(row);
            });

        // --- 3. Create Workbook ---
        const ws = XLSX.utils.aoa_to_sheet(sheetData);

        // Auto-width columns
        const wscols = [
            { wch: 30 }, // Nama
            { wch: 15 }, // NISN
            { wch: 12 }, // Kelas
            ...uniqueDates.map(() => ({ wch: 12 })) // Date columns
        ];
        ws['!cols'] = wscols;

        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Rekap Kehadiran");

        const fileName = `Rekap_Absensi_${currentGuruName.replace(/\s+/g, '_')}_${result.start}_sd_${result.end}.xlsx`;
        XLSX.writeFile(wb, fileName);

        showToast("Excel berhasil diunduh (Pivot)", "success");

    } catch (e) {
        console.error(e);
        showToast("Gagal export Excel", "error");
    } finally {
        btn.innerHTML = originalText;
        btn.disabled = false;
    }
}

async function exportToPDF() {
    const btn = document.getElementById('btnExportPdf');
    const originalText = btn.innerHTML;
    btn.innerHTML = `<div class="loader w-4 h-4 border-white border-t-transparent inline-block"></div>`;
    btn.disabled = true;

    const result = await getExportData();
    if (!result) {
        btn.innerHTML = originalText;
        btn.disabled = false;
        return;
    }

    try {
        const { jsPDF } = window.jspdf;
        const doc = new jsPDF();

        // --- Header ---
        doc.setFontSize(16);
        doc.setFont("helvetica", "bold");
        doc.text("LAPORAN REKAPITULASI KEHADIRAN", 14, 20);

        doc.setFontSize(11);
        doc.setFont("helvetica", "normal");
        doc.text(`Guru Wali: ${currentGuruName}`, 14, 30);
        doc.text(`Periode: ${result.start} s/d ${result.end}`, 14, 36);

        // --- Table ---
        const tableColumn = ["Tgl", "Nama Siswa", "NISN", "Kelas", "Status"];
        const tableRows = result.rows.map(row => [
            row.tanggal, 
            row.nama, 
            row.nisn, 
            row.kelas, 
            row.status
        ]);

        doc.autoTable({
            startY: 45,
            head: [tableColumn],
            body: tableRows,
            theme: 'grid',
            styles: { fontSize: 9, cellPadding: 2 },
            headStyles: { fillColor: [63, 81, 181], textColor: 255 },
            didParseCell: function(data) {
                if (data.section === 'body' && data.column.index === 4) {
                    const status = data.cell.raw;
                    if (status === 'ALPA') data.cell.styles.textColor = [220, 38, 38]; // Merah
                    if (status === 'IZIN') data.cell.styles.textColor = [202, 138, 4]; // Kuning/Oranye
                    if (status === 'SAKIT') data.cell.styles.textColor = [37, 99, 235]; // Biru
                    if (status === 'HADIR') data.cell.styles.textColor = [22, 163, 74]; // Hijau
                }
            }
        });

        doc.save(`Laporan_Kehadiran_${result.start}_sd_${result.end}.pdf`);
        showToast("PDF berhasil diunduh", "success");
    } catch (e) {
        console.error(e);
        showToast("Gagal export PDF", "error");
    } finally {
        btn.innerHTML = originalText;
        btn.disabled = false;
    }
}

