// --- DATA LOADING LOGIC ---

async function loadStudents() {
    const { data, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, jenis_kelamin, kelas(nama))')
        .eq('id_guru', state.guruId)
        .order('created_at', { ascending: true });

    if (error) {
        console.error(error);
        showToast('Gagal memuat siswa', 'error');
        return;
    }
    state.students = data || [];
}

async function loadAttendanceData() {
    state.loading = true;
    updateUIState(); // Show loading state if needed

    state.isHoliday = false;
    state.holidayInfo = null;
    state.attendance = {};
    state.originalAttendance = {};
    state.mode = 'INPUT';

    const todayStr = getLocalDateYYYYMMDD();

    try {
        // 1. Validasi Masa Depan
        if (state.date > todayStr) {
            state.isHoliday = true;
            state.holidayInfo = { jenis: 'FUTURE_DATE', keterangan: 'Tanggal Masa Depan' };
        }

        // 2. Validasi Hari Libur (Weekend)
        const dateObj = new Date(state.date);
        const day = dateObj.getDay();
        if (day === 0) { // Minggu
            state.isHoliday = true;
            state.holidayInfo = { jenis: 'HARI_NON_AKTIF', keterangan: 'Hari Minggu' };
        } else if (state.schoolConfig.hari_sekolah === 5 && day === 6) { // Sabtu
            state.isHoliday = true;
            state.holidayInfo = { jenis: 'HARI_NON_AKTIF', keterangan: 'Hari Sabtu' };
        }

        // 3. Fetch Data (Kehadiran & Kalender)
        const queries = [
            supabase.from('kehadiran').select('*').eq('id_guru', state.guruId).eq('tanggal', state.date)
        ];

        // Cek kalender hanya jika belum terdeteksi libur weekend/masa depan
        if (!state.isHoliday) {
            queries.push(
                supabase.from('kalender_pendidikan').select('jenis, keterangan').eq('tanggal', state.date).maybeSingle()
            );
        }

        const results = await Promise.all(queries);
        const kehadiranRes = results[0];
        const kalenderRes = results[1]; // Undefined if skipped

        // Cek Kalender DB
        if (kalenderRes && kalenderRes.data) {
            state.isHoliday = true;
            state.holidayInfo = kalenderRes.data;
        }

        // Process Attendance Data
        const existingData = kehadiranRes.data || [];

        if (existingData.length > 0) {
            state.mode = 'VIEW';
            state.students.forEach(item => {
                const record = existingData.find(k => k.id_siswa === item.id_siswa);
                if (record) {
                    state.attendance[item.id_siswa] = { id: record.id, status: record.status, catatan: record.catatan || '' };
                    state.originalAttendance[item.id_siswa] = { status: record.status };
                } else {
                    state.attendance[item.id_siswa] = { status: 'HADIR', catatan: '' };
                }
            });
        } else {
            state.mode = 'INPUT';
            state.students.forEach(item => {
                state.attendance[item.id_siswa] = { status: 'HADIR', catatan: '' };
            });
        }

    } catch (e) {
        console.error(e);
        showToast('Terjadi kesalahan memuat data', 'error');
    } finally {
        state.loading = false;
        updateUIState();
    }
}

// --- UI UPDATER ---

function updateUIState() {
    const badges = document.getElementById('statusBadges');
    const buttons = document.getElementById('actionButtons');
    const alertBox = document.getElementById('alertBox');
    const tbody = document.getElementById('studentListBody');

    // 1. Render Badges
