    if (state.isHoliday) {
        const bg = state.holidayInfo?.jenis === 'FUTURE_DATE' ? 'bg-slate-700 text-slate-400 border-slate-600' : 'bg-rose-500/20 text-rose-400 border-rose-500/50';
        const label = state.holidayInfo?.jenis === 'FUTURE_DATE' ? 'MASA DEPAN' : 'LIBUR / NON-AKTIF';
        badgeHtml = `<span class="px-3 py-1 text-xs font-bold uppercase tracking-wider rounded-full border ${bg}">⛔ ${label}</span>`;
    } else {
        if (state.mode === 'INPUT') badgeHtml = `<span class="px-3 py-1 bg-emerald-500/20 text-emerald-400 border border-emerald-500/50 rounded-full text-xs font-bold uppercase animate-pulse">Mode Input</span>`;
        else if (state.mode === 'VIEW') badgeHtml = `<span class="px-3 py-1 bg-blue-500/20 text-blue-400 border border-blue-500/50 rounded-full text-xs font-bold uppercase">Mode Lihat</span>`;
        else if (state.mode === 'EDIT') badgeHtml = `<span class="px-3 py-1 bg-amber-500/20 text-amber-400 border border-amber-500/50 rounded-full text-xs font-bold uppercase animate-pulse">Mode Edit</span>`;
    }
    badges.innerHTML = badgeHtml;

    // 2. Render Alert Box
    if (state.isHoliday && state.holidayInfo) {
        alertBox.className = "w-full p-4 rounded-lg flex items-start gap-3 animate-slide-in border " + (state.holidayInfo.jenis === 'FUTURE_DATE' ? 'bg-slate-700/50 border-slate-600 text-slate-300' : 'bg-rose-900/30 border-rose-600/50 text-rose-200');
        alertBox.innerHTML = `
            <i class="ph ${state.holidayInfo.jenis === 'FUTURE_DATE' ? 'ph-hourglass' : 'ph-prohibit'} text-2xl"></i>
            <div>
                <h4 class="font-bold text-sm">${state.holidayInfo.jenis === 'FUTURE_DATE' ? 'Tanggal Belum Dapat Diisi' : 'Tidak dapat menginput kehadiran'}</h4>
                <p class="text-xs opacity-90 mt-1">${state.holidayInfo.keterangan || state.holidayInfo.jenis}</p>
            </div>
        `;
        alertBox.classList.remove('hidden');
    } else {
        alertBox.classList.add('hidden');
    }

    // 3. Render Buttons
    let btnsHtml = '';
    const isDisabled = state.loading || state.students.length === 0 || state.isHoliday;

    if (state.mode === 'INPUT') {
        btnsHtml = `<button onclick="window.saveAttendance()" ${isDisabled ? 'disabled' : ''} class="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"><i class="ph ph-floppy-disk"></i> Simpan</button>`;
    } else if (state.mode === 'VIEW') {
        btnsHtml = `
            <button onclick="window.deleteAttendance()" ${state.isHoliday && state.holidayInfo?.jenis === 'FUTURE_DATE' ? 'disabled' : ''} class="bg-rose-900/50 hover:bg-rose-900 text-rose-200 border border-rose-800 px-4 py-2 rounded-lg font-medium transition flex items-center gap-2 disabled:opacity-50"><i class="ph ph-trash"></i> Hapus</button>
            ${!state.isHoliday ? `<button onclick="window.setEditMode()" class="bg-amber-600 hover:bg-amber-700 text-white px-5 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2"><i class="ph ph-pencil"></i> Ubah</button>` : ''}
        `;
    } else if (state.mode === 'EDIT') {
        btnsHtml = `
            <button onclick="window.cancelEdit()" class="bg-slate-600 hover:bg-slate-500 text-white px-4 py-2 rounded-lg font-medium transition">Batal</button>
            <button onclick="window.updateAttendance()" ${isDisabled ? 'disabled' : ''} class="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50"><i class="ph ph-check"></i> Perbarui</button>
        `;
    }
    buttons.innerHTML = btnsHtml;

    // 4. Render Table Body
    if (state.students.length === 0) {
        tbody.innerHTML = `<tr><td colspan="4" class="p-10 text-center text-slate-500 italic">Belum ada siswa binaan.</td></tr>`;
        return;
    }

    const rowHtml = state.students.map((item, idx) => {
        const studentId = item.id_siswa;
        const currentData = state.attendance[studentId] || { status: 'HADIR', catatan: '' };
        const originalStatus = state.originalAttendance[studentId]?.status;

        const isLocked = state.mode === 'VIEW' || state.isHoliday;
        const isDimmed = state.isHoliday ? 'opacity-50' : '';

        // Helper render Radio
        const renderRadio = (val, label, color) => {
            const isSelected = currentData.status === val;
            const isSavedMatch = isSelected && originalStatus === val;
            const activeClass = isSelected ? `${color} text-white ring-2 ring-white ring-opacity-50 scale-110 shadow-md` : `bg-slate-700 text-slate-400 border border-slate-600 hover:bg-slate-600`;
            const cursor = isLocked ? 'cursor-not-allowed opacity-70' : 'cursor-pointer';

            return `
                <label class="relative flex items-center justify-center w-10 h-10 rounded-lg transition-all duration-200 ${activeClass} ${cursor}">
                    <input type="radio" name="status-${studentId}" value="${val}" ${isSelected ? 'checked' : ''} 
                        onchange="window.updateLocalState('${studentId}', 'status', '${val}')" 
                        ${isLocked ? 'disabled' : ''} class="hidden">
                    ${isSavedMatch ? '<span class="text-xl font-bold">✓</span>' : `<span class="font-bold text-sm">${label}</span>`}
                </label>
            `;
        };

        return `
            <tr class="transition-colors hover:bg-slate-700/30 ${isDimmed}">
                <td class="px-6 py-4 text-center text-slate-500 text-sm">${idx + 1}</td>
                <td class="px-6 py-4">
                    <div class="flex flex-col">
                        <span class="text-sm font-bold text-white">${item.siswa?.nama}</span>
                        <span class="text-xs text-slate-400 flex gap-2">
                            <span>${item.siswa?.nisn}</span> • <span>${item.siswa?.jenis_kelamin}</span>
                        </span>
                    </div>
                </td>
                <td class="px-6 py-4">
                    <div class="flex items-center justify-center gap-3">
                        ${renderRadio('HADIR', 'H', 'bg-emerald-600')}
                        ${renderRadio('SAKIT', 'S', 'bg-amber-500')}
                        ${renderRadio('IZIN', 'I', 'bg-blue-500')}
                        ${renderRadio('ALPHA', 'A', 'bg-rose-500')}
                    </div>
                </td>
                <td class="px-6 py-4">
                    <input type="text" value="${currentData.catatan || ''}" 
                        oninput="window.updateLocalState('${studentId}', 'catatan', this.value)"
                        ${isLocked ? 'disabled' : ''}
                        placeholder="${state.mode === 'VIEW' ? '' : 'Ket...'}"
                        class="w-full bg-slate-900 border border-slate-600 text-white text-sm rounded-lg px-3 py-2 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 transition disabled:opacity-50 disabled:bg-slate-800 disabled:border-transparent">
                </td>
            </tr>
        `;
    }).join('');

    tbody.innerHTML = rowHtml;
}

// --- GLOBAL EXPORTS FOR HTML HANDLERS ---

window.updateLocalState = (studentId, key, value) => {
    if (state.mode === 'VIEW' || state.isHoliday) return;
    if (!state.attendance[studentId]) state.attendance[studentId] = {};
    state.attendance[studentId][key] = value;
    // Re-render only badges or classes if needed, but for inputs we rely on DOM binding mostly.
    // However, for Radio Buttons visuals (Checkmark logic), we might need to re-render the row or just toggle classes manually.
    // For simplicity in Vanilla JS, let's re-render shell is expensive.
    // Let's assume the "checked" state handles the radio logic, but the visual "✓" vs "Letter" needs re-eval against original.
    // To keep it reactive without React, we re-render the specific row or just rely on CSS. 
    // Re-rendering whole table is safest to ensure state consistency.
    updateUIState(); 
};

window.saveAttendance = async () => {
    if (state.isHoliday) return;
    const btn = document.querySelector('#actionButtons button');
    if(btn) { btn.disabled = true; btn.innerHTML = 'Menyimpan...'; }

    try {
        const payload = state.students.map(item => ({
            id_guru: state.guruId,
            id_siswa: item.id_siswa,
            tanggal: state.date,
            status: state.attendance[item.id_siswa].status,
            catatan: state.attendance[item.id_siswa].catatan
        }));

        const { error } = await supabase.from('kehadiran').insert(payload);
        if (error) throw error;

        showToast('Kehadiran berhasil disimpan', 'success');
        await loadAttendanceData();
    } catch (e) {
        showToast('Gagal menyimpan: ' + e.message, 'error');
        if(btn) { btn.disabled = false; btn.innerHTML = 'Simpan'; }
    }
};

window.updateAttendance = async () => {
    if (state.isHoliday) return;
    const btn = document.querySelectorAll('#actionButtons button')[1]; // Second button is Update
    if(btn) { btn.disabled = true; btn.innerHTML = 'Memproses...'; }

    try {
        const payload = state.students.map(item => {
            const form = state.attendance[item.id_siswa];
            return {
                id: form.id,
                id_guru: state.guruId,
                id_siswa: item.id_siswa,
                tanggal: state.date,
                status: form.status,
                catatan: form.catatan
            };
        });

        const { error } = await supabase.from('kehadiran').upsert(payload);
        if (error) throw error;

        showToast('Data berhasil diperbarui', 'success');
        await loadAttendanceData();
    } catch (e) {
        showToast('Gagal update: ' + e.message, 'error');
        if(btn) { btn.disabled = false; btn.innerHTML = 'Perbarui'; }
    }
};

window.deleteAttendance = async () => {
    if (state.isHoliday && state.holidayInfo?.jenis === 'FUTURE_DATE') return;
    if (!confirm('Hapus seluruh data kehadiran tanggal ini?')) return;

    try {
        const { error } = await supabase.from('kehadiran').delete().eq('id_guru', state.guruId).eq('tanggal', state.date);
        if (error) throw error;
        showToast('Data dihapus', 'warning');
        loadAttendanceData();
    } catch (e) {
        showToast('Gagal menghapus', 'error');
    }
};

window.setEditMode = () => {
    state.mode = 'EDIT';
    updateUIState();
};

window.cancelEdit = () => {
    state.mode = 'VIEW';
    // Revert changes by reloading data
    loadAttendanceData();
};

// --- EXPORT FEATURES ---

async function getExportData() {
    const start = document.getElementById('exportStartDate').value;
    const end = document.getElementById('exportEndDate').value;

    if (start > end) {
        showToast("Tanggal mulai tidak boleh lebih besar dari tanggal akhir", "error");
        return null;
    }

    showToast("Mengambil data...", "info");

    const { data, error } = await supabase
        .from('kehadiran')
        .select(`tanggal, status, siswa (nama, nisn, kelas (nama))`)
        .eq('id_guru', state.guruId)
        .gte('tanggal', start)
        .lte('tanggal', end)
        .order('tanggal', { ascending: true })
        .order('siswa(nama)', { ascending: true });

    if (error || !data || data.length === 0) {
        showToast("Tidak ada data pada periode ini", "warning");
        return null;
    }

    return { start, end, data };
}

async function exportExcelPivot() {
    const result = await getExportData();
    if (!result) return;

    try {
        const rawData = result.data;
        const uniqueDates = [...new Set(rawData.map(item => item.tanggal))].sort();
        const studentMap = {};

        // Grouping
        rawData.forEach(item => {
            const key = item.siswa?.nisn || item.siswa?.nama;
            if (!studentMap[key]) {
                studentMap[key] = { 
                    nama: item.siswa?.nama || 'Unknown', 
                    kelas: item.siswa?.kelas?.nama || '-', 
                    nisn: item.siswa?.nisn || '-', 
                    attendance: {} 
                };
            }
            studentMap[key].attendance[item.tanggal] = item.status === 'HADIR' ? 'H' : item.status === 'SAKIT' ? 'S' : item.status === 'IZIN' ? 'I' : 'A';
        });

        // Create Headers
        const headers = ["Nama Siswa", "NISN", "Kelas", ...uniqueDates];
        const sheetData = [headers];

        // Create Rows
        Object.values(studentMap)
            .sort((a, b) => a.nama.localeCompare(b.nama))
            .forEach(s => {
                const row = [s.nama, s.nisn, s.kelas, ...uniqueDates.map(d => s.attendance[d] || '-')];
                sheetData.push(row);
            });

        // Generate File
        const ws = XLSX.utils.aoa_to_sheet(sheetData);
        // Set col width
        ws['!cols'] = [{ wch: 30 }, { wch: 15 }, { wch: 10 }, ...uniqueDates.map(() => ({ wch: 5 }))];

        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Rekap Kehadiran");

        // Use Global Guru Name if available from closure or fetch
        // (Assuming currentGuruName is populated in init)
        const fileName = `Rekap_Kehadiran_${result.start}_sd_${result.end}.xlsx`;
        XLSX.writeFile(wb, fileName);

        showToast("Excel berhasil diunduh!", "success");
    } catch (e) {
        console.error(e);
        showToast("Gagal export Excel", "error");
    }
}

async function exportPdfSummary() {
    const result = await getExportData();
    if (!result) return;

    try {
        const { jsPDF } = window.jspdf;
        const doc = new jsPDF();

        // Header
        doc.setFontSize(16);
        doc.setFont("helvetica", "bold");
        doc.text("LAPORAN REKAPITULASI KEHADIRAN", 14, 20);
        doc.setFontSize(11);
        doc.setFont("helvetica", "normal");
        doc.text(`Periode: ${result.start} s/d ${result.end}`, 14, 28);

        // Process Summary Data
        const summaryMap = {};
        result.data.forEach(item => {
            const key = item.siswa?.nisn || item.siswa?.nama;
            if (!summaryMap[key]) {
                summaryMap[key] = { 
                    nama: item.siswa?.nama, 
                    kelas: item.siswa?.kelas?.nama, 
                    h: 0, s: 0, i: 0, a: 0 
                };
            }
            const s = item.status;
            if (s === 'HADIR') summaryMap[key].h++;
            else if (s === 'SAKIT') summaryMap[key].s++;
            else if (s === 'IZIN') summaryMap[key].i++;
            else if (s === 'ALPHA' || s === 'ALPA') summaryMap[key].a++;
        });

        const tableBody = Object.values(summaryMap)
            .sort((a, b) => a.nama.localeCompare(b.nama))
            .map((s, idx) => [
                idx + 1, s.nama, s.kelas, s.h, s.s, s.i, s.a, (s.s + s.i + s.a)
            ]);

        doc.autoTable({
            startY: 35,
            head: [['No', 'Nama Siswa', 'Kelas', 'H', 'S', 'I', 'A', 'Total Absen']],
            body: tableBody,
            theme: 'grid',
            headStyles: { fillColor: [63, 81, 181], textColor: 255 },
            styles: { fontSize: 9, cellPadding: 2, halign: 'center' },
            columnStyles: { 1: { halign: 'left' } } // Nama Left Align
        });

        doc.save(`Laporan_Rekap_Kehadiran_${result.start}_${result.end}.pdf`);
        showToast("PDF berhasil diunduh!", "success");

    } catch (e) {
        console.error(e);
        showToast("Gagal export PDF", "error");
    }
}

import { supabase } from '../config.js';
