import { supabase } from '../config.js';
import { showToast, getLocalDateYYYYMMDD } from '../utils.js';

// --- STATE MANAGEMENT ---
const state = {
    guruId: null,
    schoolConfig: { hari_sekolah: 5 },
    date: getLocalDateYYYYMMDD(),
    students: [],
    attendance: {}, // { studentId: { status, catatan, id } }
    originalAttendance: {}, // Snapshot DB untuk validasi UI
    mode: 'INPUT', // INPUT, VIEW, EDIT
    isHoliday: false,
    isFuture: false,
    holidayInfo: null, 
    loading: false
};

// --- INIT ---
export async function initKehadiran(guruId, schoolConfig) {
    state.guruId = guruId;
    state.schoolConfig = schoolConfig || { hari_sekolah: 5 };
    state.date = getLocalDateYYYYMMDD();

    renderShell();
    await loadStudents();
    await loadAttendanceData();
}

// --- RENDERING SHELL ---
function renderShell() {
    const today = getLocalDateYYYYMMDD();
    const startOfMonth = today.substring(0, 8) + '01';

    const content = document.getElementById('mainContent');
    content.innerHTML = `
        <div class="max-w-5xl mx-auto space-y-6 fade-in pb-20">

            <!-- SECTION 1: INPUT KEHADIRAN -->
            <div class="bg-slate-800 p-4 rounded-xl border border-slate-700 shadow-xl sticky top-0 z-20">
                <div class="flex flex-col gap-4">
                    <div class="flex flex-col lg:flex-row justify-between items-center gap-4">
                        <div class="flex items-center gap-4 w-full lg:w-auto">
                            <div class="relative">
                                <input type="date" id="inputTanggal" value="${state.date}" max="${today}" 
                                    class="bg-slate-900 border border-slate-600 text-white rounded-lg px-4 py-2 pl-10 focus:ring-2 focus:ring-indigo-500 outline-none shadow-inner font-mono">
                                <span class="absolute left-3 top-2.5 text-slate-400 text-lg"><i class="ph ph-calendar-blank"></i></span>
                            </div>
                            <div id="statusBadges"></div>
                        </div>
                        <div id="actionButtons" class="flex gap-2 w-full lg:w-auto justify-end"></div>
                    </div>
                    <div id="alertBox" class="hidden"></div>
                </div>
            </div>

            <div class="bg-slate-800 shadow-xl overflow-hidden rounded-xl border border-slate-700">
                <div class="overflow-x-auto">
                    <table class="min-w-full divide-y divide-slate-700">
                        <thead class="bg-slate-750 text-slate-400">
                            <tr>
                                <th class="px-6 py-4 text-center text-xs font-bold uppercase w-12">No</th>
                                <th class="px-6 py-4 text-left text-xs font-bold uppercase">Siswa</th>
                                <th class="px-6 py-4 text-center text-xs font-bold uppercase">Status Kehadiran</th>
                                <th class="px-6 py-4 text-left text-xs font-bold uppercase">Catatan</th>
                            </tr>
                        </thead>
                        <tbody id="studentListBody" class="bg-slate-800 divide-y divide-slate-700">
                            <tr><td colspan="4" class="p-8 text-center text-slate-500"><div class="loader mx-auto mb-2"></div>Memuat data...</td></tr>
                        </tbody>
                    </table>
                </div>
            </div>

            <!-- SECTION 2: EXPORT & LAPORAN -->
            <div class="bg-slate-800 p-6 rounded-xl border border-slate-700 shadow-lg mt-8">
                <div class="flex items-center gap-3 mb-6 border-b border-slate-700 pb-4">
                    <div class="bg-indigo-600/20 p-2.5 rounded-lg text-indigo-400"><i class="ph ph-file-text text-2xl"></i></div>
                    <div>
                        <h3 class="text-lg font-bold text-white">Laporan & Rekapitulasi</h3>
                        <p class="text-sm text-slate-400">Unduh rekap kehadiran berdasarkan rentang tanggal.</p>
                    </div>
                </div>

                <div class="grid grid-cols-1 md:grid-cols-2 gap-5 mb-6">
                    <div>
                        <label class="text-xs font-bold text-slate-500 uppercase block mb-1.5">Dari Tanggal</label>
                        <input type="date" id="exportStartDate" value="${startOfMonth}" class="w-full bg-slate-900 border border-slate-600 text-white rounded-lg p-2.5 outline-none focus:border-indigo-500 transition text-sm">
                    </div>
                    <div>
                        <label class="text-xs font-bold text-slate-500 uppercase block mb-1.5">Sampai Tanggal</label>
                        <input type="date" id="exportEndDate" value="${today}" class="w-full bg-slate-900 border border-slate-600 text-white rounded-lg p-2.5 outline-none focus:border-indigo-500 transition text-sm">
                    </div>
                </div>

                <div class="flex gap-3">
                    <button id="btnExportXls" class="flex-1 bg-green-700 hover:bg-green-600 text-white py-3 rounded-lg font-bold flex items-center justify-center gap-2 transition hover:shadow-lg border border-green-600/50">
                        <i class="ph ph-microsoft-excel-logo text-xl"></i> Excel (Pivot)
                    </button>
                    <button id="btnExportPdf" class="flex-1 bg-rose-700 hover:bg-rose-600 text-white py-3 rounded-lg font-bold flex items-center justify-center gap-2 transition hover:shadow-lg border border-rose-600/50">
                        <i class="ph ph-file-pdf text-xl"></i> PDF (Rekap)
                    </button>
                </div>
            </div>
        </div>
    `;

    document.getElementById('inputTanggal').addEventListener('change', (e) => {
        state.date = e.target.value;
        loadAttendanceData();
    });

    document.getElementById('btnExportXls').addEventListener('click', exportExcelPivot);
    document.getElementById('btnExportPdf').addEventListener('click', exportPdfSummary);
}

async function loadStudents() {
    const { data, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, jenis_kelamin, kelas(nama))')
        .eq('id_guru', state.guruId)
        .order('created_at', { ascending: true });

    if (error) { showToast('Gagal memuat siswa', 'error'); return; }
    state.students = data || [];
}

async function loadAttendanceData() {
    state.loading = true;
    updateUIState();

    state.isHoliday = false;
    state.isFuture = false;
    state.holidayInfo = null;
    state.attendance = {};
    state.originalAttendance = {};

    const todayStr = getLocalDateYYYYMMDD();

    try {
        // 1. Validasi Masa Depan (Hanya ini yang mengunci simpan)
        if (state.date > todayStr) {
            state.isFuture = true;
            state.holidayInfo = { jenis: 'FUTURE_DATE', keterangan: 'Tanggal Masa Depan (Belum dapat diisi)' };
        }

        // 2. Validasi Hari Libur (Weekend)
        const dateObj = new Date(state.date);
        const day = dateObj.getDay(); // 0=Minggu
        if (day === 0) {
            state.isHoliday = true;
            state.holidayInfo = { jenis: 'HARI_NON_AKTIF', keterangan: 'Hari Minggu' };
        } else if (state.schoolConfig.hari_sekolah === 5 && day === 6) {
            state.isHoliday = true;
            state.holidayInfo = { jenis: 'HARI_NON_AKTIF', keterangan: 'Hari Sabtu (Sekolah 5 Hari Kerja)' };
        }

        // 3. Fetch Data (Kehadiran & Kalender)
        const queries = [
            supabase.from('kehadiran').select('*').eq('id_guru', state.guruId).eq('tanggal', state.date)
        ];

        if (!state.isFuture) {
            queries.push(supabase.from('kalender_pendidikan').select('jenis, keterangan').eq('tanggal', state.date).maybeSingle());
        }

        const [kehadiranRes, kalenderRes] = await Promise.all(queries);

        if (kalenderRes?.data) {
            state.isHoliday = true;
            state.holidayInfo = kalenderRes.data;
        }

        const existingData = kehadiranRes.data || [];
        state.mode = existingData.length > 0 ? 'VIEW' : 'INPUT';

        state.students.forEach(item => {
            const record = existingData.find(k => k.id_siswa === item.id_siswa);
            if (record) {
                state.attendance[item.id_siswa] = { id: record.id, status: record.status, catatan: record.catatan || '' };
                state.originalAttendance[item.id_siswa] = { status: record.status };
            } else {
                state.attendance[item.id_siswa] = { status: 'HADIR', catatan: '' };
            }
        });

    } catch (e) {
        showToast('Terjadi kesalahan memuat data', 'error');
    } finally {
        state.loading = false;
        updateUIState();
    }
}

function updateUIState() {
    const badges = document.getElementById('statusBadges');
    const buttons = document.getElementById('actionButtons');
    const alertBox = document.getElementById('alertBox');
    const tbody = document.getElementById('studentListBody');

    // 1. Badges
    let badgeHtml = '';
    if (state.isFuture) {
        badgeHtml = `<span class="px-3 py-1 bg-slate-700 text-slate-400 border border-slate-600 rounded-full text-xs font-bold uppercase">⛔ MASA DEPAN</span>`;
    } else if (state.isHoliday) {
        badgeHtml = `<span class="px-3 py-1 bg-amber-500/20 text-amber-400 border border-amber-500/50 rounded-full text-xs font-bold uppercase animate-pulse">⚠️ HARI LIBUR</span>`;
    } else {
        const modeColor = state.mode === 'INPUT' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-blue-500/20 text-blue-400';
        badgeHtml = `<span class="px-3 py-1 ${modeColor} border border-indigo-500/50 rounded-full text-xs font-bold uppercase">Mode ${state.mode === 'INPUT' ? 'Input' : 'Lihat'}</span>`;
    }
    badges.innerHTML = badgeHtml;

    // 2. Alert Box
    if (state.holidayInfo) {
        const isFuture = state.holidayInfo.jenis === 'FUTURE_DATE';
        alertBox.className = `w-full p-4 rounded-lg flex items-start gap-3 animate-slide-in border ${isFuture ? 'bg-slate-700/50 border-slate-600 text-slate-300' : 'bg-amber-900/30 border-amber-600/50 text-amber-200'}`;
        alertBox.innerHTML = `
            <i class="ph ${isFuture ? 'ph-hourglass' : 'ph-warning'} text-2xl"></i>
            <div>
                <h4 class="font-bold text-sm">${isFuture ? 'Tanggal Terkunci' : 'Peringatan Hari Libur'}</h4>
                <p class="text-xs opacity-90 mt-1">${state.holidayInfo.keterangan || state.holidayInfo.jenis.replace(/_/g, ' ')} ${isFuture ? '' : '- <b>Input Tetap Diizinkan</b>'}</p>
            </div>
        `;
        alertBox.classList.remove('hidden');
    } else { alertBox.classList.add('hidden'); }

    // 3. Buttons (Unlock logic)
    const isDisabled = state.loading || state.students.length === 0 || state.isFuture;
    let btnsHtml = '';

    if (state.mode === 'INPUT') {
        btnsHtml = `<button onclick="window.saveAttendance()" ${isDisabled ? 'disabled' : ''} class="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"><i class="ph ph-floppy-disk"></i> Simpan</button>`;
    } else if (state.mode === 'VIEW') {
        btnsHtml = `
            <button onclick="window.deleteAttendance()" ${state.isFuture ? 'disabled' : ''} class="bg-rose-900/50 hover:bg-rose-900 text-rose-200 border border-rose-800 px-4 py-2 rounded-lg font-medium transition flex items-center gap-2 disabled:opacity-50"><i class="ph ph-trash"></i> Hapus</button>
            <button onclick="window.setEditMode()" ${state.isFuture ? 'disabled' : ''} class="bg-amber-600 hover:bg-amber-700 text-white px-5 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50"><i class="ph ph-pencil"></i> Ubah</button>
        `;
    } else { // EDIT MODE
        btnsHtml = `
            <button onclick="window.cancelEdit()" class="bg-slate-600 hover:bg-slate-500 text-white px-4 py-2 rounded-lg font-medium transition">Batal</button>
            <button onclick="window.updateAttendance()" ${isDisabled ? 'disabled' : ''} class="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50"><i class="ph ph-check"></i> Perbarui</button>
        `;
    }
    buttons.innerHTML = btnsHtml;

    // 4. Table Body
    if (state.students.length === 0) { tbody.innerHTML = `<tr><td colspan="4" class="p-10 text-center text-slate-500">Belum ada siswa binaan.</td></tr>`; return; }

    tbody.innerHTML = state.students.map((item, idx) => {
        const studentId = item.id_siswa;
        const currentData = state.attendance[studentId] || { status: 'HADIR', catatan: '' };
        const originalStatus = state.originalAttendance[studentId]?.status;
        const isLocked = state.mode === 'VIEW' || state.isFuture;

        const renderRadio = (val, label, color) => {
            const isSelected = currentData.status === val;
            const isSavedMatch = isSelected && originalStatus === val;
            const activeClass = isSelected ? `${color} text-white ring-2 ring-white ring-opacity-50 scale-110 shadow-md` : `bg-slate-700 text-slate-400 border border-slate-600 hover:bg-slate-600`;
            const cursor = isLocked ? 'cursor-not-allowed opacity-70' : 'cursor-pointer';

            return `
                <label class="relative flex items-center justify-center w-10 h-10 rounded-lg transition-all duration-200 ${activeClass} ${cursor}">
                    <input type="radio" name="status-${studentId}" value="${val}" ${isSelected ? 'checked' : ''} 
                        onchange="window.updateLocalState('${studentId}', 'status', '${val}')" 
                        ${isLocked ? 'disabled' : ''} class="hidden">
                    ${isSavedMatch ? '<span class="text-xl font-bold">✓</span>' : `<span class="font-bold text-sm">${label}</span>`}
                </label>
            `;
        };

        return `
            <tr class="transition-colors hover:bg-slate-700/30 ${state.isFuture ? 'opacity-50' : ''}">
                <td class="px-6 py-4 text-center text-slate-500 text-sm">${idx + 1}</td>
                <td class="px-6 py-4">
                    <div class="flex flex-col">
                        <span class="text-sm font-bold text-white">${item.siswa?.nama}</span>
                        <span class="text-xs text-slate-400">${item.siswa?.nisn}</span>
                    </div>
                </td>
                <td class="px-6 py-4">
                    <div class="flex items-center justify-center gap-3">
                        ${renderRadio('HADIR', 'H', 'bg-emerald-600')}
                        ${renderRadio('SAKIT', 'S', 'bg-amber-500')}
                        ${renderRadio('IZIN', 'I', 'bg-blue-500')}
                        ${renderRadio('ALPHA', 'A', 'bg-rose-500')}
                    </div>
                </td>
                <td class="px-6 py-4">
                    <input type="text" value="${currentData.catatan || ''}" 
                        oninput="window.updateLocalState('${studentId}', 'catatan', this.value)"
                        ${isLocked ? 'disabled' : ''}
