async function loadStudents() {
    const { data, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, jenis_kelamin, kelas(nama))')
        .eq('id_guru', state.guruId)
        .order('created_at', { ascending: true });

    if (error) { showToast('Gagal memuat siswa', 'error'); return; }
    state.students = data || [];
}

async function loadAttendanceData() {
    state.loading = true;
    updateUIState();

    state.attendance = {};
    state.originalAttendance = {};
    state.statusInfo = { type: 'NORMAL', message: '' };

    const todayStr = getLocalDateYYYYMMDD();

    try {
        // 1. VALIDATION LOGIC
        if (state.date > todayStr) {
            // Masa Depan -> LOCKED
            state.statusInfo = { type: 'FUTURE', message: 'Tanggal Masa Depan (Belum dapat diisi)' };
        } else {
            const d = new Date(state.date);
            const day = d.getDay();
            if (day === 0) {
                state.statusInfo = { type: 'HOLIDAY', message: 'Hari Minggu' };
            } else if (state.schoolConfig.hari_sekolah === 5 && day === 6) {
                state.statusInfo = { type: 'HOLIDAY', message: 'Hari Sabtu (Sekolah 5 Hari Kerja)' };
            } else {
                // Cek DB Calendar
                const { data: cal } = await supabase.from('kalender_pendidikan')
                    .select('jenis, keterangan').eq('tanggal', state.date).maybeSingle();
                if (cal) {
                    state.statusInfo = { type: 'HOLIDAY', message: `${cal.jenis.replace(/_/g, ' ')}: ${cal.keterangan || ''}` };
                }
            }
        }

        // 2. Fetch Data (Always fetch to show view mode)
        const { data: att } = await supabase.from('kehadiran')
            .select('*').eq('id_guru', state.guruId).eq('tanggal', state.date);

        const existingData = att || [];
        state.mode = existingData.length > 0 ? 'VIEW' : 'INPUT';

        state.students.forEach(item => {
            const record = existingData.find(x => x.id_siswa === item.id_siswa);
            if (record) {
                state.attendance[item.id_siswa] = { id: record.id, status: record.status, catatan: record.catatan || '' };
                state.originalAttendance[item.id_siswa] = { status: record.status };
            } else {
                state.attendance[item.id_siswa] = { status: 'HADIR', catatan: '' };
            }
        });

    } catch (e) { showToast('Gagal memuat data', 'error'); } 
    finally {
        state.loading = false;
        updateUIState();
    }
}

function updateUIState() {
    const badges = document.getElementById('statusBadges');
    const buttons = document.getElementById('actionButtons');
    const alertBox = document.getElementById('alertBox');
    const tbody = document.getElementById('studentListBody');

    // 1. BADGES
    if (state.statusInfo.type === 'FUTURE') {
        badges.innerHTML = `<span class="px-3 py-1 bg-slate-700 text-slate-400 border border-slate-600 rounded-full text-xs font-bold uppercase">⛔ MASA DEPAN</span>`;
    } else if (state.statusInfo.type === 'HOLIDAY') {
        badges.innerHTML = `<span class="px-3 py-1 bg-amber-500/20 text-amber-400 border border-amber-500/50 rounded-full text-xs font-bold uppercase animate-pulse">⚠️ HARI LIBUR</span>`;
    } else {
        const color = state.mode === 'INPUT' ? 'emerald' : 'blue';
        badges.innerHTML = `<span class="px-3 py-1 bg-${color}-500/20 text-${color}-400 border border-${color}-500/50 rounded-full text-xs font-bold uppercase">Mode ${state.mode === 'INPUT' ? 'Input' : 'Lihat'}</span>`;
    }

    // 2. ALERT BOX
    if (state.statusInfo.type !== 'NORMAL') {
        const isFuture = state.statusInfo.type === 'FUTURE';
        alertBox.className = `w-full p-4 rounded-lg flex items-start gap-3 animate-slide-in border ${isFuture ? 'bg-red-900/30 border-red-600/50 text-red-200' : 'bg-amber-900/30 border-amber-600/50 text-amber-200'}`;
