        .eq('id_guru', state.guruId)
        .gte('tanggal', start).lte('tanggal', end)
        .order('tanggal', { ascending: true });

    if (error || !data || data.length === 0) { showToast("Data tidak ditemukan", "warning"); return null; }
    return { start, end, data };
}

async function exportExcelPivot() {
    const res = await fetchExportData();
    if (!res) return;
    try {
        const uniqueDates = [...new Set(res.data.map(i => i.tanggal))].sort();
        const studentMap = {};
        res.data.forEach(i => {
            const key = i.siswa?.nisn || i.siswa?.nama;
            if (!studentMap[key]) studentMap[key] = { nama: i.siswa?.nama, nisn: i.siswa?.nisn, kelas: i.siswa?.kelas?.nama, att: {} };
            studentMap[key].att[i.tanggal] = i.status.charAt(0);
        });

        const headers = ["Nama Siswa", "NISN", "Kelas", ...uniqueDates];
        const sheetData = [headers, ...Object.values(studentMap).map(s => [s.nama, s.nisn, s.kelas, ...uniqueDates.map(d => s.att[d] || '-')])];

        const ws = XLSX.utils.aoa_to_sheet(sheetData);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Rekap");
        XLSX.writeFile(wb, `Rekap_Kehadiran_${res.start}_sd_${res.end}.xlsx`);
        showToast("Excel berhasil diunduh", "success");
    } catch (e) { showToast("Gagal export Excel", "error"); }
}

async function exportPdfSummary() {
    const res = await fetchExportData();
    if (!res) return;
    try {
        const { jsPDF } = window.jspdf;
        const doc = new jsPDF();
        doc.setFontSize(16); doc.text("REKAPITULASI KEHADIRAN", 14, 20);
        doc.setFontSize(11); doc.text(`Periode: ${res.start} s/d ${res.end}`, 14, 28);

        const summaryMap = {};
        res.data.forEach(i => {
            const key = i.siswa?.nama;
            if (!summaryMap[key]) summaryMap[key] = { nama: key, h:0, s:0, i:0, a:0 };
            const s = i.status;
            if (s === 'HADIR') summaryMap[key].h++;
            else if (s === 'SAKIT') summaryMap[key].s++;
            else if (s === 'IZIN') summaryMap[key].i++;
            else summaryMap[key].a++;
        });

        const body = Object.values(summaryMap).map((s, idx) => [idx+1, s.nama, s.h, s.s, s.i, s.a, (s.s+s.i+s.a)]);
        doc.autoTable({
            startY: 35,
            head: [['No', 'Nama Siswa', 'H', 'S', 'I', 'A', 'Total Absen']],
            body: body,
            theme: 'grid',
            headStyles: { fillColor: [63, 81, 181] }
        });
        doc.save(`Rekap_Kehadiran_${res.start}_${res.end}.pdf`);
        showToast("PDF berhasil diunduh", "success");
    } catch (e) { showToast("Gagal export PDF", "error"); }
}

import { supabase } from '../config.js';
import { showToast, getLocalDateYYYYMMDD } from '../utils.js';

// ==========================================
// 1. STATE MANAGEMENT
// ==========================================
const state = {
    // Context
    guruId: null,
    schoolConfig: { hari_sekolah: 5 },

    // Data
    date: getLocalDateYYYYMMDD(),
    students: [],
    attendanceMap: {}, // { [id_siswa]: { status, catatan, id_db } }

    // UI State
    loading: false,
    mode: 'INPUT', // 'INPUT' | 'VIEW' | 'EDIT'

    // Validation State
    lockStatus: {
        isLocked: false,
        reason: '',
        type: 'NONE' // 'FUTURE' | 'HOLIDAY' | 'WEEKEND' | 'NONE'
    }
};

// ==========================================
// 2. INITIALIZATION
// ==========================================
export async function initKehadiran(guruId, schoolConfig) {
    state.guruId = guruId;
    state.schoolConfig = schoolConfig || { hari_sekolah: 5 };
    state.date = getLocalDateYYYYMMDD();

    renderShell();

    try {
        await loadStudents();
        await loadDataAndValidate(); // Main Logic Loop
    } catch (error) {
        console.error(error);
        showToast('Gagal memuat data awal.', 'error');
    }
}

// ==========================================
// 3. CORE LOGIC (ASYNC FLOW)
// ==========================================

async function loadStudents() {
    state.loading = true;
    updateUI(); // Show loading spinner in table

    const { data, error } = await supabase
        .from('bimbingan')
        .select('*, siswa(id, nama, nisn, jenis_kelamin, kelas(nama))')
        .eq('id_guru', state.guruId)
        .order('created_at', { ascending: true });

    if (error) throw error;
    state.students = data || [];
    state.loading = false;
}

// Fungsi Utama: Validasi Tanggal -> Cek Kalender DB -> Cek Kehadiran DB -> Tentukan State UI
async function loadDataAndValidate() {
    state.loading = true;
    updateUI(); // Set loading UI

    // Reset State Lokal
    state.attendanceMap = {};
    state.lockStatus = { isLocked: false, reason: '', type: 'NONE' };
    state.mode = 'INPUT';

    const todayStr = getLocalDateYYYYMMDD();

    try {
        // --- A. VALIDASI LOKAL (Masa Depan & Weekend) ---
        if (state.date > todayStr) {
            state.lockStatus = { isLocked: true, type: 'FUTURE', reason: 'Tanggal Masa Depan' };
        } else {
            const dateObj = new Date(state.date);
            const day = dateObj.getDay(); // 0=Minggu, 6=Sabtu

            if (day === 0) {
                state.lockStatus = { isLocked: true, type: 'WEEKEND', reason: 'Hari Minggu' };
            } else if (state.schoolConfig.hari_sekolah === 5 && day === 6) {
                state.lockStatus = { isLocked: true, type: 'WEEKEND', reason: 'Hari Sabtu (Sekolah 5 Hari)' };
            }
        }

        // --- B. FETCH DATA (Parallel) ---
        // Kita fetch data kehadiran & kalender sekaligus
        const queries = [
            supabase.from('kehadiran').select('*').eq('id_guru', state.guruId).eq('tanggal', state.date)
        ];

        // Jika belum terkunci secara lokal, cek kalender di DB
        if (!state.lockStatus.isLocked) {
            queries.push(
                supabase.from('kalender_pendidikan')
                    .select('jenis, keterangan')
                    .eq('tanggal', state.date)
                    .maybeSingle()
            );
        }

        const results = await Promise.all(queries);
        const attendanceData = results[0].data || [];
        const calendarData = results[1]?.data;

        // --- C. VALIDASI DATABASE (Kalender) ---
        if (calendarData) {
            state.lockStatus = { 
                isLocked: true, 
                type: 'HOLIDAY', 
                reason: `${calendarData.jenis.replace(/_/g, ' ')}: ${calendarData.keterangan || ''}` 
            };
        }

        // --- D. MAPPING DATA KEHADIRAN ---
        if (attendanceData.length > 0) {
            state.mode = 'VIEW'; // Data sudah ada -> Mode Lihat

            state.students.forEach(item => {
                const record = attendanceData.find(k => k.id_siswa === item.id_siswa);
                if (record) {
                    state.attendanceMap[item.id_siswa] = { 
                        id: record.id, 
                        status: record.status, 
                        catatan: record.catatan || '' 
                    };
                } else {
                    state.attendanceMap[item.id_siswa] = { status: 'HADIR', catatan: '' }; // Fallback
                }
            });
        } else {
            state.mode = 'INPUT'; // Data kosong -> Mode Input

            state.students.forEach(item => {
                state.attendanceMap[item.id_siswa] = { status: 'HADIR', catatan: '' };
            });
        }

    } catch (error) {
        console.error(error);
        showToast('Gagal memuat data kehadiran', 'error');
    } finally {
        state.loading = false;
        updateUI(); // Render final UI state
    }
}

