function updateUI() {
    const badges = document.getElementById('statusBadges');
    const buttons = document.getElementById('actionButtons');
    const alertBox = document.getElementById('alertBox');
    const tbody = document.getElementById('studentListBody');

    // 1. Loading State Table
    if (state.loading) {
        tbody.innerHTML = `<tr><td colspan="4" class="p-12 text-center text-slate-500"><div class="loader mx-auto mb-2"></div>Memproses data...</td></tr>`;
        buttons.innerHTML = '';
        badges.innerHTML = '';
        alertBox.className = "hidden";
        return;
    }

    // 2. Status Badges & Alert Box
    let badgeHtml = '';

    if (state.lockStatus.isLocked) {
        const isFuture = state.lockStatus.type === 'FUTURE';
        const bgBadge = isFuture ? 'bg-slate-700 border-slate-600 text-slate-400' : 'bg-rose-900/30 border-rose-800 text-rose-300';
        badgeHtml = `<span class="px-3 py-1 rounded-full border text-xs font-bold uppercase ${bgBadge}">⛔ ${state.lockStatus.type.replace('_', ' ')}</span>`;

        // Show Alert Box
        alertBox.className = `w-full p-4 rounded-lg flex items-start gap-3 border animate-slide-in ${isFuture ? 'bg-slate-800 border-slate-600 text-slate-400' : 'bg-rose-900/20 border-rose-800 text-rose-200'}`;
        alertBox.innerHTML = `
            <i class="ph ${isFuture ? 'ph-hourglass' : 'ph-prohibit'} text-2xl shrink-0"></i>
            <div>
                <h4 class="font-bold text-sm">Input Dikunci</h4>
                <p class="text-xs opacity-90 mt-1">${state.lockStatus.reason}</p>
            </div>
        `;
        alertBox.classList.remove('hidden');
    } else {
        const modeColor = state.mode === 'INPUT' ? 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30' : 'bg-blue-500/20 text-blue-400 border-blue-500/30';
        badgeHtml = `<span class="px-3 py-1 rounded-full border text-xs font-bold uppercase ${modeColor}">Mode ${state.mode}</span>`;
        alertBox.classList.add('hidden');
    }
    badges.innerHTML = badgeHtml;

    // 3. Action Buttons
    // Logika Disable: Jika Locked, semua tombol aksi dimatikan.
    const isLocked = state.lockStatus.isLocked;
    const isEmpty = state.students.length === 0;

    let btnHtml = '';
    if (state.mode === 'INPUT') {
        btnHtml = `<button onclick="window.saveAttendance()" ${isLocked || isEmpty ? 'disabled' : ''} class="bg-emerald-600 hover:bg-emerald-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"><i class="ph ph-floppy-disk"></i> Simpan</button>`;
    } else if (state.mode === 'VIEW') {
        btnHtml = `
            <button onclick="window.deleteAttendance()" ${isLocked ? 'disabled' : ''} class="bg-rose-900/50 hover:bg-rose-900 text-rose-200 border border-rose-800 px-4 py-2 rounded-lg font-medium transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"><i class="ph ph-trash"></i> Hapus</button>
            <button onclick="window.setEditMode()" ${isLocked ? 'disabled' : ''} class="bg-amber-600 hover:bg-amber-700 text-white px-5 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"><i class="ph ph-pencil"></i> Ubah</button>
        `;
    } else { // EDIT MODE
        btnHtml = `
            <button onclick="window.cancelEdit()" class="bg-slate-600 hover:bg-slate-500 text-white px-4 py-2 rounded-lg font-medium transition">Batal</button>
            <button onclick="window.updateAttendance()" class="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg font-bold shadow-lg transition flex items-center gap-2"><i class="ph ph-check"></i> Perbarui</button>
        `;
    }
    buttons.innerHTML = btnHtml;

    // 4. Render Table Rows
    if (state.students.length === 0) {
        tbody.innerHTML = `<tr><td colspan="4" class="p-10 text-center text-slate-500 italic">Belum ada siswa binaan.</td></tr>`;
        return;
    }

    // Tentukan apakah input di table readonly
    const isInputDisabled = isLocked || state.mode === 'VIEW';
    const dimClass = isLocked ? 'opacity-50' : '';

    tbody.innerHTML = state.students.map((item, idx) => {
        const id = item.id_siswa;
        const currentData = state.attendanceMap[id] || { status: 'HADIR', catatan: '' };

        return `
            <tr class="transition-colors hover:bg-slate-700/30 ${dimClass}">
                <td class="px-6 py-4 text-center text-slate-500 text-sm">${idx + 1}</td>
                <td class="px-6 py-4">
                    <div class="flex flex-col">
                        <span class="text-sm font-bold text-white">${item.siswa?.nama}</span>
                        <span class="text-xs text-slate-400">${item.siswa?.nisn}</span>
                    </div>
                </td>
                <td class="px-6 py-4">
                    <div class="flex items-center justify-center gap-2">
                        ${renderRadioButton(id, 'HADIR', 'H', 'bg-emerald-600', currentData.status, isInputDisabled)}
                        ${renderRadioButton(id, 'SAKIT', 'S', 'bg-amber-500', currentData.status, isInputDisabled)}
                        ${renderRadioButton(id, 'IZIN', 'I', 'bg-blue-500', currentData.status, isInputDisabled)}
                        ${renderRadioButton(id, 'ALPHA', 'A', 'bg-rose-500', currentData.status, isInputDisabled)}
                    </div>
                </td>
                <td class="px-6 py-4">
                    <input type="text" value="${currentData.catatan}" 
                        oninput="window.updateLocalState('${id}', 'catatan', this.value)"
                        ${isInputDisabled ? 'disabled' : ''}
                        class="w-full bg-slate-900 border border-slate-600 text-white text-sm rounded-lg px-3 py-2 focus:ring-1 focus:ring-indigo-500 outline-none transition disabled:bg-slate-800 disabled:border-transparent disabled:text-slate-400">
                </td>
            </tr>
        `;
    }).join('');
}

function renderRadioButton(id, val, label, color, currentStatus, disabled) {
    const isSelected = currentStatus === val;
    const activeClass = isSelected 
        ? `${color} text-white ring-2 ring-white ring-opacity-50 scale-110 shadow-md` 
        : `bg-slate-700 text-slate-400 border border-slate-600 hover:bg-slate-600`;

    const cursor = disabled ? 'cursor-not-allowed' : 'cursor-pointer';

    return `
        <label class="relative flex items-center justify-center w-10 h-10 rounded-lg transition-all duration-200 ${activeClass} ${cursor}">
            <input type="radio" name="status-${id}" value="${val}" ${isSelected ? 'checked' : ''} 
                onchange="window.updateLocalState('${id}', 'status', '${val}')" 
                ${disabled ? 'disabled' : ''} class="hidden">
            <span class="font-bold text-sm">${label}</span>
        </label>
    `;
}

// ==========================================
// 5. GLOBAL HANDLERS (EXPOSED TO WINDOW)
// ==========================================

window.updateLocalState = (id, key, val) => {
    // Prevent update if locked or view mode
    if (state.lockStatus.isLocked || state.mode === 'VIEW') return;

    if (state.attendanceMap[id]) {
        state.attendanceMap[id][key] = val;
        // Optimization: Update DOM classes manually for radio buttons instead of full re-render
        if(key === 'status') updateUI(); 
    }
};

window.saveAttendance = async () => {
    if (state.lockStatus.isLocked) return;

    setBtnLoading(true, 'Menyimpan...');
    try {
        const payload = state.students.map(item => ({
            id_guru: state.guruId,
            id_siswa: item.id_siswa,
            tanggal: state.date,
            status: state.attendanceMap[item.id_siswa].status,
            catatan: state.attendanceMap[item.id_siswa].catatan
        }));

        const { error } = await supabase.from('kehadiran').insert(payload);
        if (error) throw error;

        showToast('Kehadiran berhasil disimpan', 'success');
        await loadDataAndValidate();
    } catch (e) {
        showToast('Gagal menyimpan: ' + e.message, 'error');
        setBtnLoading(false, 'Simpan');
    }
};

window.updateAttendance = async () => {
    if (state.lockStatus.isLocked) return;

    setBtnLoading(true, 'Memperbarui...');
    try {
        const payload = state.students.map(item => ({
            id: state.attendanceMap[item.id_siswa].id,
            id_guru: state.guruId,
            id_siswa: item.id_siswa,
            tanggal: state.date,
            status: state.attendanceMap[item.id_siswa].status,
            catatan: state.attendanceMap[item.id_siswa].catatan
        }));

        const { error } = await supabase.from('kehadiran').upsert(payload);
        if (error) throw error;

        showToast('Data berhasil diperbarui', 'success');
        await loadDataAndValidate();
    } catch (e) {
        showToast('Gagal update: ' + e.message, 'error');
        setBtnLoading(false, 'Perbarui');
    }
};

window.deleteAttendance = async () => {
    if (state.lockStatus.isLocked) return;
    if (!confirm('Hapus seluruh data kehadiran tanggal ini?')) return;

    try {
        const { error } = await supabase.from('kehadiran').delete().eq('id_guru', state.guruId).eq('tanggal', state.date);
        if (error) throw error;
        showToast('Data dihapus', 'warning');
        await loadDataAndValidate();
    } catch (e) {
        showToast('Gagal menghapus', 'error');
    }
};

window.setEditMode = () => {
    if (state.lockStatus.isLocked) return;
    state.mode = 'EDIT';
    updateUI();
};

window.cancelEdit = () => {
    loadDataAndValidate(); // Revert to DB state
};

function setBtnLoading(isLoading, text) {
    const btn = document.querySelector('#actionButtons button:last-child');
    if (btn) {
        btn.disabled = isLoading;
        btn.innerHTML = isLoading ? `<div class="loader w-4 h-4 border-white border-t-transparent inline-block mr-2"></div>${text}` : text;
    }
}

// ==========================================
// 6. EXPORT LOGIC
// ==========================================

async function fetchExportData() {
    const start = document.getElementById('exportStartDate').value;
    const end = document.getElementById('exportEndDate').value;

    if (start > end) { showToast("Range tanggal tidak valid", "error"); return null; }

    showToast("Mengunduh data...", "info");
    const { data, error } = await supabase.from('kehadiran')
        .select(`tanggal, status, siswa (nama, nisn, kelas (nama))`)
        .eq('id_guru', state.guruId)
        .gte('tanggal', start).lte('tanggal', end)
        .order('tanggal', { ascending: true });

    if (error || !data || data.length === 0) { 
        showToast("Tidak ada data pada periode ini", "warning"); 
        return null; 
    }
    return { start, end, data };
}

async function exportExcelPivot() {
    const res = await fetchExportData();
    if (!res) return;
    try {
        const uniqueDates = [...new Set(res.data.map(i => i.tanggal))].sort();
        const studentMap = {};
        res.data.forEach(i => {
            const key = i.siswa?.nisn || i.siswa?.nama;
            if (!studentMap[key]) studentMap[key] = { nama: i.siswa?.nama, nisn: i.siswa?.nisn, kelas: i.siswa?.kelas?.nama, att: {} };
            studentMap[key].att[i.tanggal] = i.status.charAt(0);
        });

        const headers = ["Nama Siswa", "NISN", "Kelas", ...uniqueDates];
        const sheetData = [headers, ...Object.values(studentMap).map(s => [s.nama, s.nisn, s.kelas, ...uniqueDates.map(d => s.att[d] || '-')])];

        const ws = XLSX.utils.aoa_to_sheet(sheetData);
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, "Rekap");
        XLSX.writeFile(wb, `Rekap_Kehadiran_${res.start}_sd_${res.end}.xlsx`);
        showToast("Excel berhasil diunduh", "success");
    } catch (e) { showToast("Gagal export Excel", "error"); }
}

async function exportPdfSummary() {
    const res = await fetchExportData();
    if (!res) return;
    try {
        const { jsPDF } = window.jspdf;
        const doc = new jsPDF();
        doc.setFontSize(16); doc.text("REKAPITULASI KEHADIRAN", 14, 20);
        doc.setFontSize(11); doc.text(`Periode: ${res.start} s/d ${res.end}`, 14, 28);

        const summaryMap = {};
        res.data.forEach(i => {
            const key = i.siswa?.nama;
            if (!summaryMap[key]) summaryMap[key] = { nama: key, h:0, s:0, i:0, a:0 };
            const s = i.status;
            if (s === 'HADIR') summaryMap[key].h++;
            else if (s === 'SAKIT') summaryMap[key].s++;
            else if (s === 'IZIN') summaryMap[key].i++;
            else summaryMap[key].a++;
        });

        const body = Object.values(summaryMap).map((s, idx) => [idx+1, s.nama, s.h, s.s, s.i, s.a, (s.s+s.i+s.a)]);
        doc.autoTable({
            startY: 35,
            head: [['No', 'Nama Siswa', 'H', 'S', 'I', 'A', 'Total Absen']],
            body: body,
            theme: 'grid',
            headStyles: { fillColor: [63, 81, 181] }
        });
        doc.save(`Rekap_Kehadiran_${res.start}_${res.end}.pdf`);
        showToast("PDF berhasil diunduh", "success");
    } catch (e) { showToast("Gagal export PDF", "error"); }
}

