import { supabase } from './config.js';
import { renderLayout, setActiveRoute } from './layout.js';
import { renderLogin, attachLoginEvents } from './pages/login.js';
import { initKehadiran } from './pages/kehadiran.js';
import { initPrestasi } from './pages/prestasi.js';
import { initPelanggaran } from './pages/pelanggaran.js';
import { initJadwal } from './pages/jadwal.js';
import { initNilai } from './pages/nilai.js';
import { initLaporan } from './pages/laporan.js';
import { showToast, renderLoader } from './utils.js';

// --- STATE ---
let currentGuru = null;
let activeView = 'KEHADIRAN';
let schoolConfig = { hari_sekolah: 5 };

const app = document.getElementById('app');
const SESSION_KEY = 'gurwal_session_v2';

// --- INIT ---
async function initApp() {
    checkSession();
}

function checkSession() {
    try {
        const stored = localStorage.getItem(SESSION_KEY);
        if (stored) {
            const session = JSON.parse(stored);
            if (session && session.guru) {
                currentGuru = session.guru;
                loadDashboard();
                return;
            }
        }
    } catch (e) { localStorage.removeItem(SESSION_KEY); }
    showLogin();
}

function showLogin() {
    app.innerHTML = renderLogin();
    attachLoginEvents((guruData) => {
        currentGuru = guruData;
        localStorage.setItem(SESSION_KEY, JSON.stringify({ guru: guruData }));
        showToast(`Selamat datang, ${guruData.nama}!`);
        loadDashboard();
    });
}

async function loadDashboard() {
    // Load config first
    try {
        const { data } = await supabase.from('sekolah').select('hari_sekolah').limit(1).maybeSingle();
        if (data) schoolConfig.hari_sekolah = data.hari_sekolah;
    } catch(e) { console.log('Config load error', e); }

    // Render Layout
    app.innerHTML = renderLayout(currentGuru.nama, currentGuru.username);

    // Attach Global Nav Logic
    window.navigateTo = (view) => {
        activeView = view;
        setActiveRoute(view); // Update Sidebar State

        // Auto-close sidebar on mobile
        window.closeSidebar();

        const contentEl = document.getElementById('mainContent');
        if(contentEl) {
            contentEl.innerHTML = renderLoader();
            // Small delay to allow UI to paint loader before processing logic
            setTimeout(() => routePage(view, contentEl), 50);
        }
    };

    window.logout = () => {
        localStorage.removeItem(SESSION_KEY);
        window.location.reload();
    };

    window.toggleSidebar = () => {
        const sidebar = document.getElementById('sidebar');
        const overlay = document.getElementById('sidebarOverlay');
        if(sidebar && overlay) {
            sidebar.classList.toggle('-translate-x-full');
            overlay.classList.toggle('hidden');
        }
    };

    window.closeSidebar = () => {
        const sidebar = document.getElementById('sidebar');
        const overlay = document.getElementById('sidebarOverlay');
        if(sidebar && overlay) {
            sidebar.classList.add('-translate-x-full');
            overlay.classList.add('hidden');
        }
    };

    // Default Route
    window.navigateTo('KEHADIRAN');
}

function routePage(view, container) {
    switch (view) {
        case 'KEHADIRAN':
            initKehadiran(currentGuru.id, schoolConfig);
            break;
        case 'PRESTASI':
            initPrestasi(currentGuru.id);
            break;
        case 'PELANGGARAN':
            initPelanggaran(currentGuru.id);
            break;
        case 'JADWAL':
            initJadwal(currentGuru.id);
            break;
        case 'NILAI':
            initNilai(currentGuru.id);
            break;
        case 'LAPORAN':
            initLaporan(currentGuru.id);
            break;
        default:
            container.innerHTML = `<div class="p-10 text-center text-gray-500">Halaman tidak ditemukan</div>`;
    }
}

// Start
initApp();

