          ${menuItem("NILAI", "ph-exam", "Input Nilai")}

          <div class="pt-4 pb-2 px-4 text-[10px] font-bold text-slate-500 uppercase tracking-wider">Laporan</div>
          ${menuItem("LAPORAN", "ph-file-text", "Laporan Binaan")}
        </nav>

        <div class="p-4 border-t border-slate-700 bg-slate-800">
          <button onclick="window.logout()"
            class="w-full text-left px-4 py-2.5 rounded-lg text-red-400 hover:bg-red-500/10 hover:text-red-300 transition flex items-center gap-3 group">
            <i class="ph ph-sign-out text-lg group-hover:-translate-x-1 transition-transform"></i> Logout
          </button>
        </div>
      </aside>

      <!-- Main Content -->
      <main class="flex-1 flex flex-col relative h-full overflow-hidden w-full">
        <!-- Mobile Header -->
        <header class="md:hidden bg-slate-800 border-b border-slate-700 p-4 flex justify-between items-center z-20 shadow-md">
            <div class="flex items-center gap-3">
                <button onclick="window.toggleSidebar()" class="text-slate-300 hover:text-white p-1">
                    <i class="ph ph-list text-2xl"></i>
                </button>
                <h1 id="mobileHeaderTitle" class="font-bold text-white text-lg capitalize">Menu</h1>
            </div>
            <div class="w-8 h-8 rounded-full bg-slate-700 flex items-center justify-center text-xs font-bold text-slate-300 border border-slate-600">
                ${initial}
            </div>
        </header>

        <div id="mainContent" class="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-900 custom-scrollbar relative">
           <!-- Content injected by router -->
        </div>
      </main>

    </div>
  `;
}

function menuItem(route, icon, label) {
  const isActive = currentRoute === route;

  const activeClass = isActive
      ? "bg-indigo-600 text-white shadow-lg shadow-indigo-900/50"
      : "text-slate-400 hover:bg-slate-700 hover:text-white";

  return `
    <button onclick="window.navigateTo('${route}')" data-route="${route}"
      class="sidebar-link w-full text-left px-4 py-3 rounded-lg transition-all duration-200 flex items-center gap-3 font-medium text-sm group ${activeClass}">
      <i class="ph ${icon} text-lg ${isActive ? '' : 'group-hover:scale-110 transition-transform'}"></i> 
      <span>${label}</span>
    </button>
  `;
}

export function setActiveRoute(route) {
  currentRoute = route;

  // Update DOM classes manually to avoid full re-render
  document.querySelectorAll('.sidebar-link').forEach(el => {
      const isTarget = el.dataset.route === route;

      if (isTarget) {
          el.className = "sidebar-link w-full text-left px-4 py-3 rounded-lg transition-all duration-200 flex items-center gap-3 font-medium text-sm group bg-indigo-600 text-white shadow-lg shadow-indigo-900/50";
      } else {
          el.className = "sidebar-link w-full text-left px-4 py-3 rounded-lg transition-all duration-200 flex items-center gap-3 font-medium text-sm group text-slate-400 hover:bg-slate-700 hover:text-white";
      }
  });

  // Update Mobile Header Title
  const mobileTitle = document.getElementById('mobileHeaderTitle');
  if(mobileTitle) mobileTitle.innerText = route.replace('_', ' ');
}

import { supabase } from './config.js';
import { renderLayout, setActiveRoute } from './layout.js';
import { renderLogin, attachLoginEvents } from './pages/login.js';
import { initKehadiran } from './pages/kehadiran.js';
import { initPrestasi } from './pages/prestasi.js';
import { initPelanggaran } from './pages/pelanggaran.js';
import { initJadwal } from './pages/jadwal.js';
import { initNilai } from './pages/nilai.js';
import { initLaporan } from './pages/laporan.js';
import { showToast, renderLoader } from './utils.js';

// --- STATE ---
let currentGuru = null;
let activeView = 'KEHADIRAN';
let schoolConfig = { hari_sekolah: 5 };

const app = document.getElementById('app');
const SESSION_KEY = 'gurwal_session_v2';

// --- INIT ---
async function initApp() {
    checkSession();
}

function checkSession() {
    try {
        const stored = localStorage.getItem(SESSION_KEY);
        if (stored) {
            const session = JSON.parse(stored);
            if (session && session.guru) {
                currentGuru = session.guru;
                loadDashboard();
                return;
            }
        }
    } catch (e) { localStorage.removeItem(SESSION_KEY); }
    showLogin();
}

function showLogin() {
    app.innerHTML = renderLogin();
    attachLoginEvents((guruData) => {
        currentGuru = guruData;
        localStorage.setItem(SESSION_KEY, JSON.stringify({ guru: guruData }));
        showToast(`Selamat datang, ${guruData.nama}!`);
        loadDashboard();
    });
}

async function loadDashboard() {
    // Load config first
    try {
        const { data } = await supabase.from('sekolah').select('hari_sekolah').limit(1).maybeSingle();
        if (data) schoolConfig.hari_sekolah = data.hari_sekolah;
    } catch(e) { console.log('Config load error', e); }

    // Render Layout
    app.innerHTML = renderLayout(currentGuru.nama, currentGuru.username);

    // Attach Global Nav Logic
    window.navigateTo = (view) => {
        activeView = view;
        setActiveRoute(view); // Update Sidebar State

        // Auto-close sidebar on mobile
        window.closeSidebar();

        const contentEl = document.getElementById('mainContent');
        if(contentEl) {
            contentEl.innerHTML = renderLoader();
            // Small delay to allow UI to paint loader before processing logic
            setTimeout(() => routePage(view, contentEl), 50);
        }
    };

    window.logout = () => {
        localStorage.removeItem(SESSION_KEY);
        window.location.reload();
    };

    window.toggleSidebar = () => {
        const sidebar = document.getElementById('sidebar');
        const overlay = document.getElementById('sidebarOverlay');
        if(sidebar && overlay) {
            sidebar.classList.toggle('-translate-x-full');
            overlay.classList.toggle('hidden');
        }
    };

    window.closeSidebar = () => {
        const sidebar = document.getElementById('sidebar');
        const overlay = document.getElementById('sidebarOverlay');
        if(sidebar && overlay) {
            sidebar.classList.add('-translate-x-full');
            overlay.classList.add('hidden');
        }
    };

    // Default Route
    window.navigateTo('KEHADIRAN');
}

function routePage(view, container) {
    switch (view) {
        case 'KEHADIRAN':
            initKehadiran(currentGuru.id, schoolConfig);
            break;
        case 'PRESTASI':
            initPrestasi(currentGuru.id);
            break;
        case 'PELANGGARAN':
            initPelanggaran(currentGuru.id);
            break;
        case 'JADWAL':
            initJadwal(currentGuru.id);
            break;
        case 'NILAI':
            initNilai(currentGuru.id);
            break;
        case 'LAPORAN':
            initLaporan(currentGuru.id);
            break;
        default:
            container.innerHTML = `<div class="p-10 text-center text-gray-500">Halaman tidak ditemukan</div>`;
    }
}

// Start
initApp();

