      <div id="listSiswa" class="space-y-3">
        ${renderList()}
      </div>

      <button id="btnSimpanKehadiran"
        class="bg-indigo-600 hover:bg-indigo-700 px-5 py-2 rounded font-bold text-white">
        Simpan Kehadiran
      </button>

    </div>
  `;
}

function renderList() {
  if (siswaBinaan.length === 0) {
    return `<p class="text-slate-400">Tidak ada siswa binaan.</p>`;
  }

  return siswaBinaan
    .map(
      (s) => `
      <div class="flex justify-between items-center bg-slate-800 p-3 rounded-lg">
        <div>
          <p class="text-white font-medium">${s.nama}</p>
          <p class="text-xs text-slate-400">${s.nisn || "-"}</p>
        </div>

        <select data-id="${s.id}"
          class="status-select bg-slate-700 text-white px-2 py-1 rounded">
          <option value="HADIR">Hadir</option>
          <option value="IZIN">Izin</option>
          <option value="SAKIT">Sakit</option>
          <option value="ALPA">Alpa</option>
        </select>
      </div>
    `
    )
    .join("");
}

async function loadSiswa(guruId) {
  const { data } = await supabase
    .from("bimbingan")
    .select("siswa(*)")
    .eq("id_guru", guruId);

  siswaBinaan = data?.map((d) => d.siswa) || [];
}

export function attachKehadiranEvents(user) {
  const btn = document.getElementById("btnSimpanKehadiran");
  const inputTanggal = document.getElementById("tanggalInput");

  if (inputTanggal) {
    inputTanggal.addEventListener("change", (e) => {
      tanggalDipilih = e.target.value;
    });
  }

  if (btn) {
    btn.addEventListener("click", async () => {
      await simpanKehadiran(user.id);
    });
  }
}

async function simpanKehadiran(guruId) {
  try {
    const selects = document.querySelectorAll(".status-select");

    const payload = [];

    selects.forEach((select) => {
      payload.push({
        id_siswa: select.dataset.id,
        id_guru: guruId,
        tanggal: tanggalDipilih,
        status: select.value,
      });
    });

    const { error } = await supabase
      .from("kehadiran")
      .upsert(payload, {
        onConflict: "id_siswa,tanggal",
      });

    if (error) throw error;

    showToast("Kehadiran berhasil disimpan ✅");
  } catch (err) {
    console.error(err);
    showToast("Gagal menyimpan kehadiran ❌", "error");
  }
}

